insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1918','animals','Mammals','easy','classic','What is the largest living marsupial?','["Red kangaroo","Koala","Tasmanian devil","Virginia opossum"]'::jsonb,'Red kangaroo','The red kangaroo is the largest living marsupial.',10,2,array['mammals'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1919','animals','Classification','hard','classic','What kind of amphibian is a caecilian?','["A limbless amphibian, often adapted for burrowing","A tree frog with adhesive toe pads","A salamander with external gills throughout adulthood","A reptile with a shell"]'::jsonb,'A limbless amphibian, often adapted for burrowing','Caecilians are limbless amphibians; many species spend much of their lives underground or in leaf litter.',10,2,array['classification'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1920','animals','Mammals','easy','classic','What do mammals produce to nourish their young?','["Milk","Pollen","Silk","Nectar"]'::jsonb,'Milk','Mammals feed their young with milk produced by mammary glands.',10,2,array['mammals'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1921','animals','Diet','easy','classic','What do pangolins mainly eat?','["Ants and termites","Leaves and grass","Fish and krill","Fruit and nuts"]'::jsonb,'Ants and termites','Pangolins use long sticky tongues to eat ants and termites.',10,2,array['diet'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1922','animals','Marine life','medium','classic','Which fish group includes species that can migrate between fresh and salt water?','["Salmonids","Seahorses","Pipefishes","Sunfishes"]'::jsonb,'Salmonids','Many salmonids hatch in fresh water, grow in the ocean, and return to rivers to spawn.',10,2,array['marine life'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1923','animals','Adaptations','medium','classic','Why do fennec foxes have very large ears?','["They help release body heat","They store water","They protect the eyes from sand","They act as swimming paddles"]'::jsonb,'They help release body heat','The fennec fox''s large ears help dissipate heat in its hot desert habitat.',10,2,array['adaptations'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1924','animals','Senses','medium','classic','Which sensory structures help sharks detect weak electrical fields?','["Ampullae of Lorenzini","Barbels of Weber","Lateral scales of Darwin","Canals of Havers"]'::jsonb,'Ampullae of Lorenzini','Ampullae of Lorenzini are sensory organs that detect weak electrical fields in water.',10,2,array['senses'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1925','animals','Animal groups','easy','classic','What is a commonly used name for a group of dolphins?','["A pod","A pride","A colony","A litter"]'::jsonb,'A pod','A group of dolphins is commonly called a pod.',10,2,array['animal groups'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1926','animals','Animal relationships','medium','classic','What is kleptoparasitism?','["A feeding strategy in which an animal takes food obtained by another","A relationship in which both species benefit","A seasonal migration between habitats","A behavior in which an animal sheds its skin"]'::jsonb,'A feeding strategy in which an animal takes food obtained by another','Kleptoparasitism occurs when an animal steals food another animal has caught or collected.',10,2,array['animal relationships'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1927','animals','Classification','medium','classic','What scientific group includes whales, dolphins, and porpoises?','["Cetaceans","Pinnipeds","Sirenians","Mustelids"]'::jsonb,'Cetaceans','Whales, dolphins, and porpoises belong to the mammalian order Cetacea.',10,2,array['classification'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1928','animals','Animal behavior','easy','classic','What does crepuscular mean about an animal’s activity?','["It is mainly active around dawn and dusk","It is mainly active at midday","It is active only during winter","It remains active only underground"]'::jsonb,'It is mainly active around dawn and dusk','Crepuscular animals are most active around twilight, near dawn or dusk.',10,2,array['animal behavior'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1929','animals','Ecology','medium','classic','What is a bioindicator species?','["A species whose condition or presence can provide evidence about environmental quality","A species that is always the largest in its habitat","A species that lives only in captivity","A species that migrates to every continent"]'::jsonb,'A species whose condition or presence can provide evidence about environmental quality','Bioindicator species can provide clues about environmental conditions through their presence, absence, or health.',10,2,array['ecology'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1930','animals','Adaptations','medium','classic','Why can some lizards shed part of their tail when seized by a predator?','["The distraction can help them escape","The tail becomes a source of oxygen","The tail instantly turns into a new limb","The tail makes a loud warning call"]'::jsonb,'The distraction can help them escape','Tail shedding can distract a predator while the lizard escapes; some species later regrow part of it.',10,2,array['adaptations'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1931','animals','Ecology','easy','classic','What do scavengers mainly do in a food web?','["Feed on animals that are already dead","Make sunlight through photosynthesis","Pollinate every flowering plant","Turn rocks directly into soil"]'::jsonb,'Feed on animals that are already dead','Scavengers consume dead animals and help return nutrients to ecosystems.',10,2,array['ecology'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1932','animals','Life cycles','medium','classic','Which animal group commonly has egg, larva, pupa, and adult stages?','["Butterflies","Earthworms","Lizards","Sharks"]'::jsonb,'Butterflies','Butterflies undergo complete metamorphosis with egg, larval, pupal, and adult stages.',10,2,array['life cycles'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1933','animals','Animal senses','medium','classic','What are vibrissae in many mammals?','["Specialized whiskers that provide tactile information","Feathers that help steer in flight","Scales that sense water pressure","Claws used to groom fur"]'::jsonb,'Specialized whiskers that provide tactile information','Vibrissae are sensory hairs that help an animal detect nearby objects and changes in airflow.',10,2,array['animal senses'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1934','animals','Life cycles','hard','classic','What is ecdysis?','["The periodic shedding of an outer covering as an animal grows","The seasonal movement of animals between habitats","The conversion of a larva into an adult","The formation of a protective egg shell"]'::jsonb,'The periodic shedding of an outer covering as an animal grows','Ecdysis is the shedding of an outer cuticle or skin, as seen in arthropods and some vertebrates.',10,2,array['life cycles'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1935','animals','Conservation','hard','classic','What does the term endemic mean for a species?','["It is native to and restricted to a particular area","It migrates across every continent","It lives only in zoos","It has recently become extinct worldwide"]'::jsonb,'It is native to and restricted to a particular area','An endemic species is native to and naturally found only in a defined geographic area.',10,2,array['conservation'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1936','animals','Adaptations','hard','classic','What is countershading in an animal?','["A darker upper surface and lighter underside that can reduce visibility","A pattern that glows only underwater","A seasonal change from scales to feathers","A warning call copied from a predator"]'::jsonb,'A darker upper surface and lighter underside that can reduce visibility','Countershading can make an animal less conspicuous by reducing the appearance of its body shape.',10,2,array['adaptations'],'en',true,'Smithsonian National Zoo animal fact sheets — https://nationalzoo.si.edu/animals') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1937','birds','Migration','easy','classic','Which bird is known for an exceptionally long annual migration between Arctic and Antarctic regions?','["Arctic tern","House sparrow","Common pheasant","European robin"]'::jsonb,'Arctic tern','Arctic terns migrate between Arctic breeding areas and the Antarctic region each year.',10,2,array['migration'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1938','birds','Feeding','medium','classic','Which birds are known to feed their young with crop milk?','["Pigeons and doves","Eagles and hawks","Ducks and geese","Swifts and swallows"]'::jsonb,'Pigeons and doves','Parent pigeons and doves produce crop milk, a nutrient-rich secretion that helps feed their chicks.',10,2,array['feeding'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1939','birds','Bird anatomy','hard','classic','What does a brood patch help an incubating bird do?','["Transfer body warmth directly to its eggs","Store food for its chicks","Keep water out of its nostrils","Produce oil for its feathers"]'::jsonb,'Transfer body warmth directly to its eggs','In many species, a brood patch has few or no feathers, allowing close contact and heat transfer to eggs.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1940','birds','Bird development','medium','classic','What does altricial describe about a newly hatched bird?','["It is helpless and depends on its parents","It can fly immediately","It hatches with adult plumage and hunts alone","It is born underwater"]'::jsonb,'It is helpless and depends on its parents','Altricial chicks hatch relatively undeveloped and need substantial parental care.',10,2,array['bird development'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1941','birds','Bird development','medium','classic','What does precocial describe about some hatchlings?','["They are relatively mobile and developed soon after hatching","They remain inside the egg for several years","They are unable to move until adulthood","They hatch without a beak"]'::jsonb,'They are relatively mobile and developed soon after hatching','Precocial young, such as many ducklings, are relatively developed and mobile soon after hatching.',10,2,array['bird development'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1942','birds','Bird anatomy','medium','classic','What does a nictitating membrane do in many birds?','["It sweeps across the eye to protect and moisten it","It filters food from seawater","It stores scent chemicals for navigation","It holds the beak closed while feeding"]'::jsonb,'It sweeps across the eye to protect and moisten it','A nictitating membrane is a translucent third eyelid that can protect the eye while allowing some vision.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1943','birds','Bird development','easy','classic','What is a bird''s molt?','["The replacement of feathers","A special kind of nest","A call used only at dawn","A layer of fat around an egg"]'::jsonb,'The replacement of feathers','Molt is the regular shedding and replacement of feathers.',10,2,array['bird development'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1944','birds','Bird anatomy','medium','classic','What is the wingspan of a bird?','["The distance from one wingtip to the other with wings extended","The length of its tail feathers only","The height of its nest above ground","The distance it can dive underwater"]'::jsonb,'The distance from one wingtip to the other with wings extended','Wingspan measures the distance between the tips of the extended wings.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1945','birds','Classification','easy','classic','What is a raptor?','["A bird of prey","A bird that cannot swim","A bird that eats only fruit","A flightless seabird"]'::jsonb,'A bird of prey','Raptor is a common term for a bird of prey, such as an eagle or hawk.',10,2,array['classification'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1946','birds','Conservation','medium','classic','What does bird banding help researchers study?','["Movement, survival, and population patterns","The exact age of every feather","How birds make clouds","The mineral content of eggshells only"]'::jsonb,'Movement, survival, and population patterns','Marking individual birds with bands lets researchers learn about movement and survival.',10,2,array['conservation'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1947','birds','Bird behavior','medium','classic','What is a lek in bird behavior?','["A display area where males gather to court potential mates","A nest built entirely underwater","A flock''s winter feeding ground","A hollow bone that stores air"]'::jsonb,'A display area where males gather to court potential mates','At a lek, males display in a shared area while females visit to choose mates.',10,2,array['bird behavior'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1948','birds','Bird anatomy','medium','classic','What is a bird’s furcula commonly called?','["The wishbone formed by the fused clavicles","The sound-producing organ near the windpipe","The expandable part of the digestive tract","The longest feather on the tail"]'::jsonb,'The wishbone formed by the fused clavicles','A bird’s furcula, or wishbone, is formed by the fused clavicles.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1949','birds','Bird anatomy','hard','classic','What does the uropygial gland produce in many birds?','["An oily secretion used during feather care","The calcium shell around an egg","A liquid that digests seeds in the crop","A pigment that makes bones hollow"]'::jsonb,'An oily secretion used during feather care','Many birds spread oil from the uropygial gland while preening, though its functions vary by species.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1950','birds','Bird behavior','medium','classic','Why do some birds perform a dust bath?','["Dust can help maintain feathers and remove parasites","It keeps their eggs warm inside the body","It helps them breathe underwater","It replaces the need to molt"]'::jsonb,'Dust can help maintain feathers and remove parasites','Dust bathing is a feather-maintenance behavior that can help remove excess oil and parasites.',10,2,array['bird behavior'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1951','birds','Bird anatomy','hard','classic','What is a bird''s cere?','["The fleshy area at the base of the bill around the nostrils","The stiff central shaft of a wing feather","The joint that bends the wing","A small pouch used to store swallowed food"]'::jsonb,'The fleshy area at the base of the bill around the nostrils','The cere is the soft, often bare area at the base of the beak that surrounds the nostrils in many birds.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1952','birds','Flight','medium','classic','What does a bird’s alula help it do during slow flight?','["Maintain lift and control airflow near the wing","Filter salt from seawater","Grind food in the gizzard","Keep eggs warm before they are laid"]'::jsonb,'Maintain lift and control airflow near the wing','The alula is a small group of feathers on the wing’s thumb-like structure that aids control at low speeds.',10,2,array['flight'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1953','birds','Bird development','medium','classic','What is a fledgling?','["A young bird that has left the nest but may still receive parental care","A chick that has not yet hatched","An adult bird that has finished migrating","An egg that has just been laid"]'::jsonb,'A young bird that has left the nest but may still receive parental care','A fledgling has left the nest and is developing flight skills; parents may continue to feed it.',10,2,array['bird development'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1954','birds','Bird anatomy','hard','classic','What are rectrices?','["The flight feathers in a bird’s tail","The long flight feathers on a bird’s outer wing","The soft down feathers of a hatchling","The feathers that cover a bird’s eyelids"]'::jsonb,'The flight feathers in a bird’s tail','Rectrices are tail feathers that help with steering and braking in flight.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1955','birds','Bird behavior','medium','classic','What does roosting describe in bird behavior?','["Settling at a place to rest or sleep, often at night","Building a nest from mud underwater","Changing feathers into scales","Searching for a mate by displaying at a lek"]'::jsonb,'Settling at a place to rest or sleep, often at night','Roosting is the act of resting or sleeping at a regular or sheltered site.',10,2,array['bird behavior'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict (id) do nothing;
