insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2073','history','Modern history','hard','classic','What was the primary aim of the 1944 Bretton Woods conference?','["Design postwar monetary and financial institutions","Create a permanent court for war crimes","Set rules for Antarctic exploration","Begin the construction of the Berlin Wall"]'::jsonb,'Design postwar monetary and financial institutions','The Bretton Woods conference shaped the postwar monetary system and led to institutions including the IMF and World Bank.',10,2,array['modern history'],'en',true,'Encyclopaedia Britannica History & Society — https://www.britannica.com/browse/History-Society') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2074','history','Ancient world','medium','classic','Which writing material was made from a plant along the Nile and used in ancient Egypt?','["Papyrus","Parchment made from silk","Bamboo paper from the Andes","Linen made from cedar bark"]'::jsonb,'Papyrus','Ancient Egyptians made a writing surface from strips of the papyrus plant.',10,2,array['ancient world'],'en',true,'Encyclopaedia Britannica History & Society — https://www.britannica.com/browse/History-Society') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2075','history','World history','hard','classic','What did the Haitian Revolution achieve by 1804?','["Independence of Haiti from French colonial rule","The unification of Haiti and Cuba","The end of slavery throughout the entire Atlantic world","The creation of the League of Nations"]'::jsonb,'Independence of Haiti from French colonial rule','The Haitian Revolution ended French colonial rule in Saint-Domingue and led to Haiti’s independence in 1804.',10,2,array['world history'],'en',true,'Encyclopaedia Britannica History & Society — https://www.britannica.com/browse/History-Society') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2076','history','Ancient world','hard','classic','Which ancient Greek historian is often called the father of history?','["Herodotus","Aristotle","Sophocles","Archimedes"]'::jsonb,'Herodotus','Herodotus wrote an extensive account of the Greco-Persian Wars and is often called the father of history.',10,2,array['ancient world'],'en',true,'Encyclopaedia Britannica History & Society — https://www.britannica.com/browse/History-Society') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2077','technology','Networks','easy','classic','What is a packet in computer networking?','["A formatted unit of data carried by a network protocol","A physical box used to store a router","A password that unlocks a wireless connection","A cable used only for telephone calls"]'::jsonb,'A formatted unit of data carried by a network protocol','Network protocols organize transmitted information into packets or similar units.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2078','technology','Networks','medium','classic','What does a transport-layer port number help identify?','["An application or service endpoint on a device","The physical location of a network cable","The length of an internet address","The strength of a wireless signal"]'::jsonb,'An application or service endpoint on a device','Transport-layer port numbers help direct network traffic to the appropriate application or service on a host.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2079','technology','Security','medium','classic','What does a certificate authority typically issue to help verify a server’s identity online?','["A digital certificate","A domain name resolver","A software patch","A network packet"]'::jsonb,'A digital certificate','A certificate authority signs digital certificates that bind a public key to an identity, helping clients authenticate a server during TLS connections.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2080','technology','Security','medium','classic','What is smishing?','["A phishing attempt delivered through text messages","A method for compressing video files","A wireless standard for connecting printers","A program that detects spelling errors"]'::jsonb,'A phishing attempt delivered through text messages','Smishing uses deceptive SMS or text messages to trick recipients into unsafe actions.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2081','technology','Security','hard','classic','What is a passkey commonly used for?','["Signing in with a cryptographic credential instead of a traditional password","Measuring how fast a network cable transfers data","Encrypting a file by changing its extension","Creating a backup copy of a screen"]'::jsonb,'Signing in with a cryptographic credential instead of a traditional password','A passkey uses public-key cryptography to authenticate a user to a service.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2082','technology','Hardware','medium','classic','What is a CPU cache used for?','["Keeping frequently accessed data close to the processor for faster access","Storing files permanently after power is off","Converting analog sound into radio waves","Cooling the computer’s power supply"]'::jsonb,'Keeping frequently accessed data close to the processor for faster access','A CPU cache holds copies of data or instructions that the processor may need soon, reducing access time compared with main memory.',10,2,array['hardware'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2083','technology','Hardware','medium','classic','What does an arithmetic logic unit (ALU) do?','["Performs arithmetic and logical operations on data","Stores files when a computer is turned off","Displays images on a monitor","Connects a computer to a wireless network"]'::jsonb,'Performs arithmetic and logical operations on data','An ALU is a processor component that performs arithmetic calculations and logical comparisons.',10,2,array['hardware'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2084','technology','Hardware','hard','classic','What does wear leveling do in flash-memory storage?','["Distributes write and erase cycles across memory blocks","Makes every stored file read-only","Converts flash memory into magnetic storage","Deletes all data whenever the device restarts"]'::jsonb,'Distributes write and erase cycles across memory blocks','Wear leveling spreads write and erase activity across flash blocks to reduce uneven wear and extend usable life.',10,2,array['hardware'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2085','technology','Networks','medium','classic','What is latency in a computer network?','["The delay between sending data and receiving a response","The total number of computers in a building","The brightness of a device’s display","The amount of storage in a router"]'::jsonb,'The delay between sending data and receiving a response','Network latency is the time delay involved in data transfer or response.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2086','technology','Networks','medium','classic','What does NFC stand for in contactless communication?','["Near Field Communication","Network Frequency Control","New File Container","National Fiber Connection"]'::jsonb,'Near Field Communication','Near Field Communication enables short-range exchanges, such as contactless payments.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2087','technology','Networks','medium','classic','What is GPS primarily used to determine?','["Position and time using satellite signals","The chemical makeup of soil","The speed of a computer processor","The age of a web page"]'::jsonb,'Position and time using satellite signals','The Global Positioning System uses satellite signals to calculate position and precise time.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2088','technology','Software','medium','classic','What does a compiler do?','["Translates source code into another form that a computer can execute or process","Creates a wireless connection between two phones","Checks whether a battery is fully charged","Turns every data file into a photograph"]'::jsonb,'Translates source code into another form that a computer can execute or process','A compiler translates source code into machine code or another target representation.',10,2,array['software'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2089','technology','Software','easy','classic','What is a software patch?','["A small update that corrects a defect or addresses a security issue","A physical cover placed over a computer screen","A file format used only for photographs","A password that never expires"]'::jsonb,'A small update that corrects a defect or addresses a security issue','A software patch changes part of a program to fix a bug, improve behavior, or address a vulnerability.',10,2,array['software'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2090','technology','Security','hard','classic','What is a honeypot in cybersecurity?','["A decoy system designed to attract and monitor attackers","A password shared by every employee","A device that blocks all incoming electricity","A file that compresses encrypted messages"]'::jsonb,'A decoy system designed to attract and monitor attackers','A honeypot is a decoy resource used to observe or study unauthorized activity.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2091','technology','Networks','medium','classic','What does bandwidth describe for a communications link?','["Its capacity to carry data over a period of time","The physical width of a network cable","The time needed to encrypt one file","The number of passwords stored on a device"]'::jsonb,'Its capacity to carry data over a period of time','Bandwidth describes a link’s data-carrying capacity, commonly expressed in bits per second.',10,2,array['networks'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2092','technology','Data','medium','classic','What is a checksum used for?','["Checking data for accidental changes or transmission errors","Making a file impossible to copy","Changing an image into a sound","Increasing the physical size of a hard drive"]'::jsonb,'Checking data for accidental changes or transmission errors','A checksum can help detect accidental corruption or changes in data.',10,2,array['data'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
