insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2095','technology','Data','hard','classic','What is a database index designed to improve?','["The speed of finding rows for certain queries","The accuracy of every value entered","The amount of memory in a phone","The resolution of a display"]'::jsonb,'The speed of finding rows for certain queries','A database index can speed up searches and lookups, at the cost of storage and update work.',10,2,array['data'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2096','technology','Security','hard','classic','What is end-to-end encryption intended to ensure?','["Only the communicating endpoints can read the message content","Every network operator can read the message","The message is permanently stored on a public server","The sender''s device cannot see what it sends"]'::jsonb,'Only the communicating endpoints can read the message content','End-to-end encryption is designed so that only the intended endpoints hold keys to read message content.',10,2,array['security'],'en',true,'NIST Computer Security Resource Center glossary — https://csrc.nist.gov/glossary ; MDN Web Docs — https://developer.mozilla.org/ ; IETF TLS 1.3 specification, RFC 8446 — https://www.rfc-editor.org/rfc/rfc8446 ; W3C WAI, Understanding Focus Visible — https://www.w3.org/WAI/WCAG22/Understanding/focus-visible.html ; Encyclopaedia Britannica, Computer — https://www.britannica.com/technology/computer') on conflict (id) do nothing;
