insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2119','civics','Constitution','medium','classic','What is judicial review?','["The power of courts to assess whether laws or actions follow a constitution","The process of counting votes after an election","A rule that judges write the annual budget","A method for selecting a jury"]'::jsonb,'The power of courts to assess whether laws or actions follow a constitution','Judicial review allows courts to evaluate laws or government actions against constitutional rules.',10,2,array['constitution'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
