insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2121','civics','Government','medium','classic','What is a common role of an opposition party in a legislature?','["Scrutinize the government and offer alternative policies","Appoint every judge without legal limits","Count the national population each year","Replace all local elections with court hearings"]'::jsonb,'Scrutinize the government and offer alternative policies','Opposition parties commonly question government decisions, scrutinize policy, and present alternative proposals.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2122','civics','Constitution','medium','classic','What is a constitutional amendment?','["A formal change or addition to a constitution","A temporary campaign promise","A routine court hearing","A census of the population"]'::jsonb,'A formal change or addition to a constitution','An amendment formally changes or adds to a constitution under its prescribed process.',10,2,array['constitution'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2123','civics','Government','medium','classic','What does due process generally require?','["Fair procedures before government deprives a person of a protected right","A rule that every court case must end in a fine","A guarantee that every legal claim will succeed","A system in which laws apply only to citizens"]'::jsonb,'Fair procedures before government deprives a person of a protected right','Due process refers to legally required fair procedures, with details set by each legal system.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2124','civics','Elections','medium','classic','What is proportional representation intended to do in an election?','["Allocate seats in a way that broadly reflects votes received","Let courts appoint every representative","Require every voter to support two candidates","End the need to count ballots"]'::jsonb,'Allocate seats in a way that broadly reflects votes received','Proportional representation systems aim to make representation broadly correspond to votes, according to their rules.',10,2,array['elections'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2125','civics','Government','hard','classic','What is a filibuster in some legislative systems?','["A procedural tactic used to delay or block a vote, often by extending debate","A court order that cancels an election","A public petition signed by legislators","A committee report that automatically becomes law"]'::jsonb,'A procedural tactic used to delay or block a vote, often by extending debate','A filibuster is a procedural tactic—often involving prolonged debate—used in some legislatures to delay or prevent a vote.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2126','civics','Government','medium','classic','Why are checks and balances used in government?','["To limit the concentration of power among branches or institutions","To make every public decision unanimous","To prevent legislatures from debating laws","To let one branch control all public offices"]'::jsonb,'To limit the concentration of power among branches or institutions','Checks and balances allow institutions to limit or review one another''s powers.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2127','civics','Government','medium','classic','What does a census count?','["The population and related characteristics of a country or area","Only the number of government buildings","The number of laws passed in a day","The results of a court appeal"]'::jsonb,'The population and related characteristics of a country or area','A census systematically counts a population and gathers information about it.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2128','civics','Government','medium','classic','What is an executive order?','["A directive issued by an executive authority to guide government operations","A final judgment issued by an appellate court","A formal change made to a constitution","A request asking a public authority to consider an issue"]'::jsonb,'A directive issued by an executive authority to guide government operations','An executive order is a directive from an executive branch authority; its scope and legal effect depend on the jurisdiction and applicable law.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2129','civics','Government','medium','classic','What is a coalition government?','["A government formed when multiple political parties cooperate to govern","A court made up of several judges","A legislature with only one elected member","A public vote on a single proposal"]'::jsonb,'A government formed when multiple political parties cooperate to govern','A coalition government is formed when parties join together to secure or exercise governing power.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2130','civics','Indian civics','medium','classic','Which article of India’s Constitution describes India as a Union of States?','["Article 1","Article 14","Article 21","Article 32"]'::jsonb,'Article 1','Article 1 describes India as a Union of States and specifies its territory.',10,2,array['indian civics'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2131','civics','Indian civics','hard','classic','What is a no-confidence motion in India’s Lok Sabha intended to test?','["Whether the Council of Ministers retains the confidence of the House","Whether a court may review a law","Whether a state may change its boundaries","Whether a bill has received presidential assent"]'::jsonb,'Whether the Council of Ministers retains the confidence of the House','A no-confidence motion tests whether the government retains majority support in the Lok Sabha.',10,2,array['indian civics'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2132','civics','Public access','medium','classic','What do freedom-of-information laws generally allow people to request?','["Access to records held by public authorities, subject to legal exemptions","Access to another person’s private medical files without consent","A court ruling without filing a case","A change to the constitution by individual request"]'::jsonb,'Access to records held by public authorities, subject to legal exemptions','Freedom-of-information laws generally provide a process for requesting public records, with exemptions set by law.',10,2,array['public access'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2133','civics','Indian civics','hard','classic','What is public-interest litigation in India generally used to address?','["A matter of public concern or rights through a court petition","A dispute over the price of shares in a private company","A request to register a new political party","A routine application for a passport"]'::jsonb,'A matter of public concern or rights through a court petition','Public-interest litigation can let a petitioner seek judicial attention to matters affecting the public, subject to court rules.',10,2,array['indian civics'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2134','civics','Government','medium','classic','What is transparency in public administration?','["Making decisions and relevant information open to scrutiny","Keeping every public decision secret","Allowing officials to avoid written records","Replacing laws with informal promises"]'::jsonb,'Making decisions and relevant information open to scrutiny','Transparency enables the public to understand and scrutinize government actions and decisions.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2135','civics','Indian civics','medium','classic','What is the normal term of office for an elected member of India’s Rajya Sabha?','["Six years","Two years","Four years","Ten years"]'::jsonb,'Six years','A Rajya Sabha member normally serves a six-year term, with about one-third of the members retiring every two years.',10,2,array['indian civics'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2136','civics','Courts','hard','classic','What does appellate jurisdiction allow a court to do?','["Review decisions made by lower courts or tribunals","Write laws for the legislature","Conduct a population census","Issue passports to people who apply"]'::jsonb,'Review decisions made by lower courts or tribunals','A court with appellate jurisdiction can review decisions from lower courts under the applicable rules of appeal.',10,2,array['courts'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2137','economics','Markets','medium','classic','What is a price taker in a competitive market?','["A participant who cannot influence the market price on their own","A regulator who sets every price by law","A seller who always charges more than competitors","A buyer who refuses to purchase at any price"]'::jsonb,'A participant who cannot influence the market price on their own','A price taker accepts the market price because its individual buying or selling activity is too small to determine it.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2138','economics','National accounts','medium','classic','What does a business cycle describe?','["Fluctuations in overall economic activity, including expansions and contractions","The daily change in one company’s share price","A rule that prices must remain unchanged","The sequence in which a household pays its bills"]'::jsonb,'Fluctuations in overall economic activity, including expansions and contractions','A business cycle describes recurring rises and falls in broad economic activity; its phases vary in length and strength.',10,2,array['national accounts'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2139','economics','Prices','medium','classic','What does stagflation describe?','["A period of weak economic activity combined with high inflation","A rapid fall in prices with strong output growth","A market in which only one firm sells a product","A budget with equal revenue and spending"]'::jsonb,'A period of weak economic activity combined with high inflation','Stagflation combines stagnant or weak economic activity with high inflation.',10,2,array['prices'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2140','economics','Markets','easy','classic','What is a substitute good?','["A product that can be used in place of another product","A product that must be consumed at the same time as another","A public service that cannot be sold","A good that is never affected by income"]'::jsonb,'A product that can be used in place of another product','Substitute goods can serve similar purposes, so consumers may switch between them.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2141','economics','Markets','medium','classic','What is producer surplus?','["The difference between the market price sellers receive and the minimum they would accept","The total amount consumers pay in sales taxes","The cost of producing every unit in an economy","The quantity of goods left unsold in a warehouse"]'::jsonb,'The difference between the market price sellers receive and the minimum they would accept','Producer surplus measures the benefit sellers receive when the market price exceeds the minimum amount they would have been willing to accept.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2142','economics','Markets','hard','classic','What is a positive externality?','["A benefit received by people who are not directly part of an activity","A tax paid only by a foreign government","A cost charged to the buyer on a receipt","A decrease in a company''s advertising budget"]'::jsonb,'A benefit received by people who are not directly part of an activity','A positive externality is a benefit to third parties that is not fully reflected in the transaction.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2143','economics','Trade','medium','classic','What is an import quota?','["A limit on the amount of a good that may be imported","A tax on household income","A discount offered by a local shop","A payment for using a public road"]'::jsonb,'A limit on the amount of a good that may be imported','An import quota places a quantitative limit on imports of a specified product.',10,2,array['trade'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2144','economics','Public finance','medium','classic','What is a tax credit?','["An amount subtracted directly from tax owed, subject to the rules that apply","A percentage added to the price of an imported good","A loan that every taxpayer must repay","A fee charged for filing a budget"]'::jsonb,'An amount subtracted directly from tax owed, subject to the rules that apply','A tax credit reduces tax liability directly; its value and refundability depend on the tax system and the specific credit.',10,2,array['public finance'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2145','economics','Money','medium','classic','What is a central bank''s monetary policy mainly intended to influence?','["Money and credit conditions in the economy","The rules of every private sports league","The names of commercial banks","The annual rainfall in a country"]'::jsonb,'Money and credit conditions in the economy','Monetary policy uses tools such as interest rates to influence money, credit, and economic conditions.',10,2,array['money'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2146','economics','Money','medium','classic','What is a bond’s coupon payment?','["The scheduled interest payment made to the bondholder","The amount of principal repaid only at maturity","A fee charged to trade the bond","The bond’s market price on the day it is issued"]'::jsonb,'The scheduled interest payment made to the bondholder','A bond coupon is its stated periodic interest payment, usually calculated from its face value and coupon rate.',10,2,array['money'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2147','economics','Money','hard','classic','What does currency appreciation mean?','["A currency rises in value relative to another currency","A banknote is replaced by a coin","A government stops publishing prices","A currency loses all purchasing power overnight"]'::jsonb,'A currency rises in value relative to another currency','Currency appreciation is an increase in value relative to another currency under the quoted exchange rate.',10,2,array['money'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2148','economics','Work','easy','classic','How is the unemployment rate commonly calculated?','["Unemployed people seeking work divided by the labour force","All residents divided by the number of businesses","Employees divided by the number of schools","People not seeking work divided by the population"]'::jsonb,'Unemployed people seeking work divided by the labour force','The unemployment rate is the share of the labour force that is unemployed and seeking work.',10,2,array['work'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2149','economics','Public finance','medium','classic','What is a public good in basic economics?','["A good that is non-excludable and non-rival in consumption","A product sold only by government shops","A private item that only one person can use","A good that must be imported"]'::jsonb,'A good that is non-excludable and non-rival in consumption','Public goods are often defined as non-excludable and non-rival, such as national defense.',10,2,array['public finance'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2150','economics','Public finance','medium','classic','What is a budget deficit?','["When spending exceeds income over a stated period","When income exactly equals spending","When exports exceed imports","When prices stop changing"]'::jsonb,'When spending exceeds income over a stated period','A budget deficit occurs when expenditure is greater than revenue during a period.',10,2,array['public finance'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2151','economics','Trade','medium','classic','What is a trade embargo?','["A government ban or substantial restriction on trade with a country or in certain goods","A discount offered to a local retailer","A measure of goods exports minus imports","A payment made by a bank to a depositor"]'::jsonb,'A government ban or substantial restriction on trade with a country or in certain goods','An embargo restricts or prohibits specified trade, often for political or security reasons.',10,2,array['trade'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2152','economics','Production','medium','classic','What is marginal cost?','["The additional cost of producing one more unit","The average price paid by all customers","The total value of a company''s shares","The cost of starting a new country"]'::jsonb,'The additional cost of producing one more unit','Marginal cost is the change in total cost from producing one additional unit.',10,2,array['production'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2153','economics','Choices','medium','classic','What is an inferior good in economics?','["A good whose demand tends to fall as consumer income rises, other things equal","A good that is always unsafe to use","A good that costs more than every substitute","A good that is supplied only by government"]'::jsonb,'A good whose demand tends to fall as consumer income rises, other things equal','For an inferior good, demand tends to decrease when income increases, holding other factors constant.',10,2,array['choices'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2154','economics','National accounts','medium','classic','What is nominal GDP?','["The value of final goods and services measured at current prices","Output adjusted to remove all changes in prices","The average income earned by each household","The value of imported goods alone"]'::jsonb,'The value of final goods and services measured at current prices','Nominal GDP values final output using prices from the period being measured.',10,2,array['national accounts'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2155','economics','Markets','hard','classic','What is a price ceiling set below the market-clearing price likely to cause?','["A shortage","A permanent surplus","No change in quantity demanded","The disappearance of all buyers"]'::jsonb,'A shortage','A binding price ceiling below equilibrium tends to increase quantity demanded and reduce quantity supplied, creating a shortage.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2156','economics','Markets','hard','classic','What does price elasticity of supply measure?','["How responsive quantity supplied is to a change in price","How responsive household income is to a change in tax","How many firms sell in a market","The cost of transporting goods between countries"]'::jsonb,'How responsive quantity supplied is to a change in price','Price elasticity of supply measures the responsiveness of quantity supplied to price changes.',10,2,array['markets'],'en',true,'IMF Back to Basics and WTO glossary — https://www.imf.org/external/pubs/ft/fandd/basics/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2157','music','Dynamics','medium','classic','What does sforzando indicate in a musical score?','["A sudden strong accent on a note or chord","A gradual increase in loudness","A gradual decrease in loudness","A smooth connection between notes"]'::jsonb,'A sudden strong accent on a note or chord','Sforzando, often abbreviated sfz, directs a sudden emphasis on the marked note or chord.',10,2,array['dynamics'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2158','music','Rhythm','easy','classic','What does a time signature tell a musician?','["How beats are grouped into measures","The instrument''s purchase price","The key of the concert hall","The number of performers in an orchestra"]'::jsonb,'How beats are grouped into measures','A time signature indicates how beats are grouped into measures and which note value represents a beat.',10,2,array['rhythm'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2159','music','Tempo','easy','classic','What does the musical direction allegro generally indicate?','["A lively, fairly quick tempo","A very soft dynamic","A gradual slowing to a stop","A passage played without rhythm"]'::jsonb,'A lively, fairly quick tempo','Allegro is a tempo marking that generally means fast and lively.',10,2,array['tempo'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2160','music','Form','hard','classic','What is a cadenza in a concerto?','["A virtuosic solo passage, often near the end of a movement","A repeated bass pattern beneath changing melodies","A short pause between two measures","A group of singers performing in unison"]'::jsonb,'A virtuosic solo passage, often near the end of a movement','A cadenza is a technically elaborate solo passage, traditionally giving a soloist room for display or improvisation.',10,2,array['form'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2161','music','Expression','medium','classic','What is portamento in music?','["A smooth glide from one pitch to another","A gradual increase in loudness","A repeated pattern played by the bass","A short silence between movements"]'::jsonb,'A smooth glide from one pitch to another','Portamento is a continuous slide between pitches rather than a sequence of separately articulated notes.',10,2,array['expression'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2162','music','Harmony','medium','classic','What is a pedal point in music?','["A sustained or repeated pitch heard while harmonies change around it","A melody played only by a keyboard instrument","A brief pause at the end of a measure","A chord made from exactly five unrelated notes"]'::jsonb,'A sustained or repeated pitch heard while harmonies change around it','A pedal point is a sustained or repeated pitch, often in the bass, beneath changing harmonies.',10,2,array['harmony'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2163','music','Harmony','medium','classic','What is a triad in common-practice tonal music?','["A chord built from three pitches arranged in thirds","A melody played by three singers only","A scale with three octaves","A rhythm with three rests and no notes"]'::jsonb,'A chord built from three pitches arranged in thirds','A triad is a three-note chord typically formed by stacking two thirds.',10,2,array['harmony'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2164','music','Music history','medium','classic','What is a leitmotif?','["A recurring musical idea associated with a person, place, or idea","The first scale degree in a key","A note that is always played loudly","A repeating time signature"]'::jsonb,'A recurring musical idea associated with a person, place, or idea','A leitmotif is a recurring musical theme linked with a character, place, or idea.',10,2,array['music history'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2165','music','Notation','medium','classic','What does a tie between two notes of the same pitch indicate?','["Hold them for their combined duration without reattacking the second note","Play the second note louder than the first","Separate the notes with a brief silence","Repeat the first note at a faster tempo"]'::jsonb,'Hold them for their combined duration without reattacking the second note','A tie joins the durations of notes with the same pitch so they sound as one sustained note.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2166','music','Texture','medium','classic','What is a canon in music?','["A composition in which parts enter successively with the same melody","A composition for one unaccompanied singer","A very soft dynamic marking","A scale arranged in descending order"]'::jsonb,'A composition in which parts enter successively with the same melody','In a canon, successive voices or instruments imitate the same musical line.',10,2,array['texture'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2167','music','Texture','medium','classic','What is monophonic musical texture?','["One melodic line without accompanying harmony","Several independent melodies at once","A melody supported by chords","A rhythm played only by drums"]'::jsonb,'One melodic line without accompanying harmony','Monophony consists of a single melodic line, whether performed by one or many voices in unison.',10,2,array['texture'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2168','music','Notation','easy','classic','What is a pickup note in music?','["A note or group of notes heard before the first complete measure","The final chord of a composition","A symbol that identifies the clef","A rest that lasts for an entire piece"]'::jsonb,'A note or group of notes heard before the first complete measure','A pickup, or anacrusis, is a short opening phrase that begins before the first complete measure.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2169','music','Form','medium','classic','What is a bridge in a popular song?','["A contrasting section that links other sections, often before a return to the chorus","A passage that repeats the opening verse word for word","A mark that tells performers to stop immediately","A sustained note played beneath changing harmonies"]'::jsonb,'A contrasting section that links other sections, often before a return to the chorus','A bridge often provides musical or lyrical contrast before the song returns to a familiar section; not every song has one.',10,2,array['form'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2170','music','Pitch','medium','classic','What is a perfect fifth in Western music?','["An interval spanning five letter names, commonly seven semitones","The smallest interval between adjacent notes","Two pitches with the same letter name an octave apart","A rhythm containing five equal measures"]'::jsonb,'An interval spanning five letter names, commonly seven semitones','A perfect fifth spans five diatonic letter names and usually seven semitones in common Western tuning.',10,2,array['pitch'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2171','music','Tempo','medium','classic','What does the marking ritardando mean?','["Gradually slow down","Gradually get louder","Play the passage twice","Return to the original key"]'::jsonb,'Gradually slow down','Ritardando instructs performers to slow the tempo gradually.',10,2,array['tempo'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2172','music','Music history','medium','classic','Which composer is strongly associated with the Brandenburg Concertos?','["Johann Sebastian Bach","Claude Debussy","Franz Schubert","Igor Stravinsky"]'::jsonb,'Johann Sebastian Bach','Johann Sebastian Bach composed the six Brandenburg Concertos around 1721.',10,2,array['music history'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2173','music','World music','easy','classic','A gamelan ensemble is traditionally associated with which region?','["Indonesia","Iceland","Peru","Morocco"]'::jsonb,'Indonesia','Gamelan is a traditional ensemble music of Indonesia, especially Java and Bali.',10,2,array['world music'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2174','music','Notation','hard','classic','What is an accidental in music notation?','["A sign that raises, lowers, or restores a note''s pitch","A symbol that changes the instrument''s size","A mark that indicates a singer''s language","A note that has no fixed pitch"]'::jsonb,'A sign that raises, lowers, or restores a note''s pitch','Accidentals alter a note from the pitch indicated by the key signature.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2175','music','Harmony','hard','classic','What is an enharmonic pair in equal temperament?','["Two differently named notes that sound the same","Two notes that are always an octave apart","A pair of instruments with matching timbres","Two rhythms with different meters"]'::jsonb,'Two differently named notes that sound the same','Enharmonic spellings such as C-sharp and D-flat share a pitch in equal temperament.',10,2,array['harmony'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2176','music','Form','hard','classic','What is a coda in a musical composition?','["A concluding section that brings the piece to an end","The opening note of a scale","A written list of rehearsal dates","A repeated bass line under every verse"]'::jsonb,'A concluding section that brings the piece to an end','A coda is a concluding passage that follows the main sections of a composition.',10,2,array['form'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict (id) do nothing;
