insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2197','vocabulary','Word relationships','easy','classic','What is a homophone?','["A word that sounds like another but has a different meaning or spelling","A word with the opposite meaning","A word borrowed from another language","A word that names an action"]'::jsonb,'A word that sounds like another but has a different meaning or spelling','Homophones sound alike but differ in meaning and often in spelling.',10,2,array['word relationships'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2198','vocabulary','Word relationships','easy','classic','What is an antonym?','["A word with an opposite meaning","A word that sounds the same","A word used only in poetry","A word formed from two initials"]'::jsonb,'A word with an opposite meaning','An antonym is a word opposite in meaning to another word.',10,2,array['word relationships'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2199','vocabulary','Word building','easy','classic','What is a prefix?','["A word part placed before a root or base","A word part placed after a root","A mark used only at the end of a sentence","A word with two syllables"]'::jsonb,'A word part placed before a root or base','A prefix is an affix added to the beginning of a word or base.',10,2,array['word building'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2200','vocabulary','Word building','easy','classic','What is a suffix?','["A word part added after a root or base","A word part placed before a root","A word that imitates a sound","A phrase with a hidden meaning"]'::jsonb,'A word part added after a root or base','A suffix is an affix attached to the end of a word or base.',10,2,array['word building'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2201','vocabulary','Word building','medium','classic','What does the prefix re- usually mean in words such as rebuild?','["Again or back","Before","Without","Across"]'::jsonb,'Again or back','In rebuild, re- indicates doing something again or restoring it.',10,2,array['word building'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2202','vocabulary','Expressions','easy','classic','What is an idiom?','["A phrase whose meaning is not simply the literal meaning of its words","A word that names a person","A sentence containing only questions","A formal list of synonyms"]'::jsonb,'A phrase whose meaning is not simply the literal meaning of its words','An idiom is an expression whose conventional meaning differs from a literal reading.',10,2,array['expressions'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2203','vocabulary','Word sound','medium','classic','What is onomatopoeia?','["The use of words that imitate sounds","The study of word origins","A word with several prefixes","A pattern of opposite meanings"]'::jsonb,'The use of words that imitate sounds','Onomatopoeia uses words that imitate or suggest sounds, such as buzz or hiss.',10,2,array['word sound'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2204','vocabulary','Word meaning','medium','classic','What is a malapropism?','["The mistaken use of a similar-sounding word, often with a humorous effect","A word that names a group","A phrase whose words are arranged alphabetically","A comparison that uses the word like"]'::jsonb,'The mistaken use of a similar-sounding word, often with a humorous effect','A malapropism is the humorous misuse of a word that resembles the intended word in sound.',10,2,array['word meaning'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2205','vocabulary','Figures of speech','medium','classic','What is a paradox?','["A statement that seems contradictory but may reveal a truth","A word with the opposite meaning","A phrase that imitates a sound","A sentence that contains no verb"]'::jsonb,'A statement that seems contradictory but may reveal a truth','A paradox appears self-contradictory yet can express a meaningful idea.',10,2,array['figures of speech'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2206','vocabulary','Word meaning','medium','classic','What is an analogy used to do?','["Explain an idea by showing a relevant similarity between two things","List every word in a dictionary","Change a noun into a verb","Show that two sounds rhyme"]'::jsonb,'Explain an idea by showing a relevant similarity between two things','An analogy uses a relationship between familiar and unfamiliar things to explain an idea.',10,2,array['word meaning'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2207','vocabulary','Word origins','hard','classic','What does etymology study?','["The origins and historical development of words","The rhythm of musical instruments","The measurement of a mountain''s height","The grammar of one sentence only"]'::jsonb,'The origins and historical development of words','Etymology studies the history and origin of words.',10,2,array['word origins'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2208','vocabulary','Figures of speech','medium','classic','What is a euphemism?','["A mild expression used in place of one considered harsh or direct","A word that imitates a sound","A term with two opposite meanings","A phrase repeated at the start of each line"]'::jsonb,'A mild expression used in place of one considered harsh or direct','A euphemism substitutes a less direct expression for one that may seem unpleasant or blunt.',10,2,array['figures of speech'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2209','vocabulary','Grammar','easy','classic','What is a collective noun?','["A noun that names a group as a unit","A noun that describes a color","A verb that shows a command","A word that links two clauses"]'::jsonb,'A noun that names a group as a unit','A collective noun refers to a group, such as team, flock, or committee.',10,2,array['grammar'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2210','vocabulary','Grammar','medium','classic','What is a transitive verb?','["A verb that takes a direct object","A verb that can only appear in the past tense","A verb that names a person","A verb with no subject"]'::jsonb,'A verb that takes a direct object','A transitive verb takes a direct object, as in she opened the door.',10,2,array['grammar'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2211','vocabulary','Word meaning','easy','classic','What is a synonym?','["A word with a similar meaning to another word","A word with the opposite meaning","A word that always has the same spelling","A word used only in a title"]'::jsonb,'A word with a similar meaning to another word','Synonyms are words with the same or similar meanings, depending on context.',10,2,array['word meaning'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2212','vocabulary','Word meaning','medium','classic','What does fastidious mean?','["Very attentive to detail and careful about quality","Present in every place at once","No longer useful or in use","Requiring very little effort"]'::jsonb,'Very attentive to detail and careful about quality','Fastidious describes careful attention to detail and standards.',10,2,array['word meaning'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2213','vocabulary','Spelling','easy','classic','Which spelling is correct for the word meaning a short, memorable saying?','["Proverb","Proverbe","Proverd","Proverp"]'::jsonb,'Proverb','Proverb is the standard spelling for a short traditional saying that expresses a general truth.',10,2,array['spelling'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2214','vocabulary','Grammar','medium','classic','What is a syllable?','["A unit of spoken language organized around a vowel sound","A punctuation mark used between clauses","A complete chapter in a book","A word that has no spoken sound"]'::jsonb,'A unit of spoken language organized around a vowel sound','A syllable is a spoken unit typically built around one vowel sound.',10,2,array['grammar'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2215','vocabulary','Word meaning','medium','classic','What does conciliatory mean?','["Intended to reduce disagreement or restore friendly relations","Requiring considerable effort","No longer used or useful","Open to several interpretations"]'::jsonb,'Intended to reduce disagreement or restore friendly relations','Conciliatory describes an approach intended to ease conflict or restore goodwill.',10,2,array['word meaning'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2216','vocabulary','Word building','hard','classic','What is a portmanteau word?','["A word formed by blending parts of two words","A word borrowed without changing its spelling","A phrase containing two opposite ideas","A word made by reversing its letters"]'::jsonb,'A word formed by blending parts of two words','A portmanteau blends sounds and meanings from two words, as in brunch from breakfast and lunch.',10,2,array['word building'],'en',true,'Merriam-Webster Dictionary — https://www.merriam-webster.com/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2217','braille','Braille structure','medium','classic','What does an eight-dot Braille cell add to a standard six-dot cell?','["Two additional dot positions in a fourth row","A second page of tactile symbols","A printed color code","Two columns of raised letters"]'::jsonb,'Two additional dot positions in a fourth row','An eight-dot cell adds two positions below the six-dot pattern, enabling additional symbols and computer Braille uses.',10,2,array['braille structure'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2218','braille','Braille literacy','medium','classic','What is the Nemeth Code used for in Braille?','["Representing mathematics and science notation","Printing Braille music only","Writing only in languages that use Cyrillic letters","Replacing all tactile diagrams with audio"]'::jsonb,'Representing mathematics and science notation','The Nemeth Code is a Braille code used to represent mathematical and scientific notation.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2219','braille','Braille access','medium','classic','What can a tactile graphic communicate to a reader?','["Information from diagrams, maps, or images through raised lines and textures","The exact color of a printed page","The sound level of a spoken sentence","The weight of a computer keyboard"]'::jsonb,'Information from diagrams, maps, or images through raised lines and textures','Tactile graphics use raised features to represent visual information such as maps and diagrams.',10,2,array['braille access'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2220','braille','Braille access','medium','classic','What is a Braille embosser used for?','["Producing raised-dot Braille on paper","Translating speech into sign language","Scanning raised dots into a photograph only","Changing a keyboard into a touchscreen"]'::jsonb,'Producing raised-dot Braille on paper','A Braille embosser prints raised dots onto paper for tactile reading.',10,2,array['braille access'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2221','braille','Braille literacy','easy','classic','Is Braille a language or a writing system?','["A writing system","A spoken language","A type of hearing aid","A mathematical operation"]'::jsonb,'A writing system','Braille is a tactile writing system that can represent many different languages.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2222','braille','Braille literacy','medium','classic','What does interpoint Braille printing mean?','["Braille is embossed on both sides of a page","Each page is printed in two languages","Raised dots are replaced with ink","Two readers share a single Braille cell"]'::jsonb,'Braille is embossed on both sides of a page','Interpoint printing places Braille on both sides of a sheet while arranging dots to avoid interference.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2223','braille','Braille literacy','medium','classic','What does Unified English Braille standardize?','["Rules for writing English in Braille across many contexts","A spoken accent used in the United Kingdom","One universal tactile alphabet for every language","A method for printing ordinary ink text"]'::jsonb,'Rules for writing English in Braille across many contexts','UEB is a code for English Braille used across literary and many other contexts.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2224','braille','Digital Braille','medium','classic','What does the .brf file extension commonly identify?','["A Braille-ready text file","A file containing only spoken audio","A scanned image of a printed page","A spreadsheet of Braille dot measurements"]'::jsonb,'A Braille-ready text file','BRF files commonly store Braille text in a form suitable for reading on a display or preparing for embossing.',10,2,array['digital braille'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2225','braille','Braille access','medium','classic','What is a Braille notetaker?','["A portable device for reading and writing digital text using Braille input or output","A paper guide for drawing straight lines","A printer that uses colored ink only","A device that converts music into speech"]'::jsonb,'A portable device for reading and writing digital text using Braille input or output','A Braille notetaker is an electronic device that supports note-taking through Braille keys and tactile output.',10,2,array['braille access'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2226','braille','Braille access','medium','classic','What does a panning button on a refreshable Braille display let a user do?','["Move the displayed text window to an earlier or later part of the text","Move the cursor directly to the character under a selected cell","Change all Braille text into printed ink","Emboss the displayed line onto paper"]'::jsonb,'Move the displayed text window to an earlier or later part of the text','Panning controls move the portion of text shown on a refreshable display, while cursor-routing buttons move the text cursor to a chosen position.',10,2,array['braille access'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2227','braille','Braille writing','medium','classic','What are a slate and stylus used for in Braille?','["Writing Braille manually by pressing dot patterns into paper","Reading digital text aloud through a speaker","Printing colored labels for medication","Measuring the spacing between lines of ink"]'::jsonb,'Writing Braille manually by pressing dot patterns into paper','A slate guides dot positions while a stylus presses the Braille pattern into paper.',10,2,array['braille writing'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2228','braille','Digital Braille','hard','classic','Which Unicode block represents Braille cell patterns as text characters?','["Braille Patterns (U+2800–U+28FF)","Greek and Coptic (U+0370–U+03FF)","CJK Unified Ideographs (U+4E00–U+9FFF)","Combining Diacritical Marks (U+0300–U+036F)"]'::jsonb,'Braille Patterns (U+2800–U+28FF)','Unicode’s Braille Patterns block encodes the 256 possible combinations of dots in a Braille cell.',10,2,array['digital braille'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2229','braille','Braille literacy','easy','classic','What does one Braille cell represent?','["A character, contraction, indicator, or other code sign","Always one complete spoken sentence","A page number only","A musical instrument"]'::jsonb,'A character, contraction, indicator, or other code sign','A Braille cell can encode a letter, number, punctuation mark, contraction, or indicator.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2230','braille','Braille music','hard','classic','In Braille music notation, what does an octave mark indicate?','["The pitch register for the following note or notes","How long the next rest lasts","Whether a passage should be played loudly","Which instrument should perform the next measure"]'::jsonb,'The pitch register for the following note or notes','Braille music uses octave marks to identify the register of notes; the note signs convey other musical information.',10,2,array['braille music'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2231','braille','Braille access','hard','classic','What does Braille translation software do?','["Converts text into Braille code according to language rules","Scans a page and changes every word into a photograph","Creates a spoken language from raised dots","Measures the height of embossed paper"]'::jsonb,'Converts text into Braille code according to language rules','Braille translation software applies code rules to convert text into a Braille representation.',10,2,array['braille access'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2232','braille','Braille literacy','hard','classic','Why may a Braille text use a grade 1 indicator before a letter sequence?','["To show that letters should be read literally rather than as contractions","To change English text into another language","To mark the end of a music score","To show that the text is printed in ink"]'::jsonb,'To show that letters should be read literally rather than as contractions','In UEB, a grade 1 indicator can prevent letters from being interpreted as contractions.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2233','braille','Braille access','hard','classic','What does a cursor-routing button on a refreshable Braille display commonly do?','["Moves the text cursor to the position represented by that Braille cell","Changes the language of every document on the device","Prints the displayed text onto paper","Turns the display into a tactile map"]'::jsonb,'Moves the text cursor to the position represented by that Braille cell','Cursor-routing buttons commonly let a user move the text cursor to the location associated with a selected display cell.',10,2,array['braille access'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2234','braille','Braille literacy','hard','classic','In Unified English Braille, what can a typeform indicator mark?','["A style such as italic or bold text","The start of a page number","The direction in which a line should be read","The location of a cursor on a display"]'::jsonb,'A style such as italic or bold text','UEB typeform indicators can show emphasis or formatting such as italics, boldface, or underlining.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2235','braille','Braille access','hard','classic','Why are consistent Braille dot patterns important in public signs?','["They let readers recognize information by touch across locations","They make signs visible from farther away","They prevent all spelling differences between languages","They allow a reader to hear a sign"]'::jsonb,'They let readers recognize information by touch across locations','Standardized dot patterns help Braille readers interpret signs consistently.',10,2,array['braille access'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2236','braille','Braille literacy','hard','classic','What can a Braille page indicator help a reader keep track of?','["A page''s position in a longer text","The reader''s typing speed","The temperature of the paper","The number of voices in an audio recording"]'::jsonb,'A page''s position in a longer text','Page indicators help readers navigate the sequence of pages in a longer Braille work.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2237','management','Projects','easy','classic','What is a project deliverable?','["A specific output or result produced by project work","A meeting held before a project begins","The person who approves every employee''s leave","A list of possible project risks only"]'::jsonb,'A specific output or result produced by project work','A deliverable is a verifiable output or result that a project is expected to produce.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2238','management','Projects','medium','classic','What is a project charter used to do?','["Formally authorize a project and state its high-level purpose and boundaries","Record every daily transaction made by a company","Schedule annual leave for an entire department","Describe the personal preferences of each customer"]'::jsonb,'Formally authorize a project and state its high-level purpose and boundaries','A project charter formally authorizes work and records high-level information such as purpose, objectives, and boundaries.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2239','management','Teams','medium','classic','What does a project sponsor typically do?','["Champions the project and provides high-level support or authorization","Performs every task assigned to the project team","Audits every customer’s personal account","Sets the market price of the project’s output"]'::jsonb,'Champions the project and provides high-level support or authorization','A project sponsor supports and advocates for a project and may provide authorization, resources, or senior-level guidance.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2240','management','Projects','medium','classic','What is a task dependency in a project schedule?','["A relationship that determines the order in which activities can occur","A record of the money already spent","A measure of employee satisfaction","A list of customers who have made a purchase"]'::jsonb,'A relationship that determines the order in which activities can occur','A task dependency links activities so that the timing or completion of one can affect another.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2241','management','Projects','medium','classic','What does a stakeholder engagement plan describe?','["How a project will communicate and work with interested parties","The number of computers in a project office","The formula for calculating annual tax","A list of tasks that have already been cancelled"]'::jsonb,'How a project will communicate and work with interested parties','A stakeholder engagement plan identifies approaches for communicating and collaborating with stakeholders.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2242','management','Teams','medium','classic','What does a RACI chart clarify?','["Who is responsible, accountable, consulted, and informed for tasks","How much revenue each product earns","The order of customers in a queue","The number of risks in a project"]'::jsonb,'Who is responsible, accountable, consulted, and informed for tasks','RACI assigns roles as Responsible, Accountable, Consulted, and Informed.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2243','management','Planning','medium','classic','What factors are considered in a PESTLE analysis?','["Political, economic, social, technological, legal, and environmental factors","People, equipment, schedules, targets, labour, and expenses","Products, exports, savings, taxes, loans, and earnings","Planning, execution, staffing, training, logistics, and evaluation"]'::jsonb,'Political, economic, social, technological, legal, and environmental factors','PESTLE is a framework for examining political, economic, social, technological, legal, and environmental influences.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2244','management','Quality','hard','classic','What does a control chart help a team monitor?','["Whether process variation stays within statistically determined limits over time","How many topics are scheduled for a meeting","Which project tasks depend on one another","The amount of cash held in a company account"]'::jsonb,'Whether process variation stays within statistically determined limits over time','A control chart plots process measurements over time with control limits to help distinguish routine variation from possible signals of change.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2245','management','Performance','medium','classic','What is a leading indicator in performance management?','["A measure that may signal future results","A score that records only past outcomes","A list of employee names","A company''s final tax payment"]'::jsonb,'A measure that may signal future results','A leading indicator can provide an early signal of future performance, unlike a lagging outcome measure.',10,2,array['performance'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2246','management','Planning','medium','classic','What does a burndown chart track during an agile iteration?','["Remaining work over time","The number of people reporting to a manager","The value of all completed company sales","The number of risks that have never been reviewed"]'::jsonb,'Remaining work over time','A burndown chart shows how much work remains over time, often against an ideal trend line.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2247','management','Teams','medium','classic','What is a matrix organization?','["A structure in which people may report to both functional and project managers","A company owned by one public agency","A schedule that lists tasks against dates","A chart showing the number of products sold"]'::jsonb,'A structure in which people may report to both functional and project managers','In a matrix structure, employees may work across functions and report to both a functional manager and a project manager.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2248','management','Planning','medium','classic','What does an issue log track on a project?','["Current problems, their owners, status, and planned actions","Only possible future risks that have not occurred","The sequence of tasks that determines the project finish date","The topics planned for the next staff meeting"]'::jsonb,'Current problems, their owners, status, and planned actions','An issue log records active problems and information such as responsibility, priority, status, and next steps.',10,2,array['planning'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2249','management','Quality','medium','classic','What is a pilot test used for before a wider rollout?','["Trying a process or product on a limited scale to find issues","Approving every final product without inspection","Replacing all project planning with a survey","Measuring a company’s annual tax rate"]'::jsonb,'Trying a process or product on a limited scale to find issues','A pilot test tries an approach with a limited group or setting so problems can be found before broader use.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2250','management','Quality','medium','classic','What is quality control primarily intended to do?','["Check outputs to identify whether they meet requirements","Write every company policy","Set interest rates for customers","Replace all process improvement work"]'::jsonb,'Check outputs to identify whether they meet requirements','Quality control inspects or tests outputs against specified requirements.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2251','management','Decision-making','medium','classic','What does a decision tree help a team analyze?','["Choices and their possible outcomes or consequences","The reporting relationships in a matrix organization","The timing of every meeting in a month","The number of units held in a warehouse"]'::jsonb,'Choices and their possible outcomes or consequences','A decision tree maps choices and possible outcomes to help compare options under uncertainty.',10,2,array['decision-making'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2252','management','Teams','medium','classic','What are meeting minutes?','["A written record of key discussions, decisions, and actions","A countdown to the next meeting","A list of invited guests who declined","A marketing plan for a new service"]'::jsonb,'A written record of key discussions, decisions, and actions','Meeting minutes record important decisions, discussion points, and assigned actions.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2253','management','Operations','hard','classic','What does value stream mapping help a team examine?','["The flow of materials and information through a process","The number of direct reports a manager has","The legal ownership of a business","The interest rate on a bank loan"]'::jsonb,'The flow of materials and information through a process','Value stream mapping visualizes process steps and flows so a team can identify delays, waste, and opportunities for improvement.',10,2,array['operations'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2254','management','Teams','medium','classic','What is constructive feedback intended to do?','["Give specific information that can help improve future work","Blame a person without explaining the issue","Replace every formal performance review","Guarantee that an idea will be accepted"]'::jsonb,'Give specific information that can help improve future work','Constructive feedback focuses on observable behavior and useful next steps.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2255','management','Projects','hard','classic','What does earned value management compare?','["Planned work, completed work, and actual cost","Employee satisfaction and office temperature","The age of a project and its final title","Customer reviews and a competitor''s website"]'::jsonb,'Planned work, completed work, and actual cost','Earned value management integrates scope, schedule, and cost to assess project performance.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2256','management','Teams','medium','classic','What is job rotation?','["Planned movement of employees between roles or tasks","A rule that requires a manager to approve every purchase","A schedule that shows a product’s expected delivery date","A method for calculating a company’s gross margin"]'::jsonb,'Planned movement of employees between roles or tasks','Job rotation moves employees between roles or tasks to broaden experience and develop skills.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2257','business','Planning','easy','classic','What is an executive summary in a business plan?','["A concise overview of the plan''s main points","A detailed record of every daily transaction","A list of all customer passwords","A receipt for the company''s first sale"]'::jsonb,'A concise overview of the plan''s main points','An executive summary briefly presents the key ideas and direction of a business plan.',10,2,array['planning'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2258','business','Customers','medium','classic','What does product-market fit describe?','["A product meeting strong demand from its intended market","A product having the lowest price in every country","A company selling only one product","A customer receiving a printed receipt"]'::jsonb,'A product meeting strong demand from its intended market','Product-market fit describes an offering that addresses a meaningful need for a target market.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2259','business','Customers','medium','classic','What is a customer persona?','["A research-informed profile representing a typical customer in a segment","A legal identity assigned to a company","A guarantee that a product will sell","A list of every competing brand"]'::jsonb,'A research-informed profile representing a typical customer in a segment','A customer persona summarizes research about a segment''s needs, goals, and behaviors.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2260','business','Ownership','medium','classic','What is a joint venture?','["A business arrangement in which parties cooperate on a defined undertaking","A business owned by one individual only","A tax charged on every imported product","A retail sale made directly to a consumer"]'::jsonb,'A business arrangement in which parties cooperate on a defined undertaking','A joint venture is a collaboration in which parties combine resources for a specific business activity while remaining separate entities.',10,2,array['ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2261','business','Ownership','medium','classic','What is a business cooperative?','["An enterprise owned and governed by its members","A company that only rents office space","A business that must be owned by a government","A sales contract between a wholesaler and retailer"]'::jsonb,'An enterprise owned and governed by its members','A cooperative is an enterprise owned and controlled by members who share its benefits according to its rules.',10,2,array['ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2262','business','Ownership','hard','classic','What does a holding company primarily do?','["Owns controlling interests in other companies","Manufactures every product sold by its subsidiaries","Insures all shipments between countries","Sets the tax rates of every business"]'::jsonb,'Owns controlling interests in other companies','A holding company primarily owns shares or other interests in subsidiaries and may oversee their governance.',10,2,array['ownership'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2263','business','Finance','medium','classic','What does return on investment compare?','["The return generated relative to the cost of an investment","Revenue relative to the number of customers","Current assets relative to current liabilities","The value of inventory relative to warehouse size"]'::jsonb,'The return generated relative to the cost of an investment','Return on investment compares a gain or return with the resources invested, using a stated calculation.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2264','business','Finance','medium','classic','What does the asset turnover ratio measure?','["How much revenue a business generates relative to its assets","The percentage of revenue remaining after direct costs","How often customers return a product","The number of suppliers used in a year"]'::jsonb,'How much revenue a business generates relative to its assets','Asset turnover compares revenue with assets and is commonly used to assess how efficiently a business uses its assets to generate sales.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2265','business','Finance','medium','classic','Why can a profitable business still face a cash shortage?','["Cash receipts and payments may occur at different times","Profit always requires a business to borrow","A profitable business cannot issue invoices","Every sale is automatically paid in cash"]'::jsonb,'Cash receipts and payments may occur at different times','A timing gap between payments and customer receipts can create a cash shortage despite reported profit.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2266','business','Planning','medium','classic','What is a business continuity plan intended to do?','["Prepare an organization to maintain or restore essential operations during a disruption","Replace a company’s annual financial statements","Set the price of every product in a market","Guarantee that a business will never face a risk"]'::jsonb,'Prepare an organization to maintain or restore essential operations during a disruption','A business continuity plan helps an organization prepare for disruptions and maintain or recover critical activities.',10,2,array['planning'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2267','business','Branding','medium','classic','What does brand positioning aim to establish?','["A distinctive place for a brand in the target audience’s mind relative to alternatives","The physical address of every retail store","The number of employees who work in marketing","A guarantee that the brand will have no competitors"]'::jsonb,'A distinctive place for a brand in the target audience’s mind relative to alternatives','Brand positioning defines how a business wants its offering to be understood and differentiated in the minds of its target customers.',10,2,array['branding'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2268','business','Operations','medium','classic','What does inventory turnover measure?','["How often stock is sold or used and replaced during a period","The number of suppliers a company has","The distance goods travel to a shop","The amount of tax paid on each sale"]'::jsonb,'How often stock is sold or used and replaced during a period','Inventory turnover relates cost of goods sold to average inventory over a period.',10,2,array['operations'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2269','business','Branding','easy','classic','What does a brand help a business do?','["Distinguish its offering and communicate an identity","Guarantee every customer will buy","Replace the need to provide a product","Hide the source of all goods"]'::jsonb,'Distinguish its offering and communicate an identity','A brand helps identify and distinguish a business or its products.',10,2,array['branding'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2270','business','Finance','medium','classic','What is a sunk cost?','["A cost already incurred that cannot be recovered","A cost that changes with each additional unit produced","A payment a customer will make next month","A cost that is always fixed by law"]'::jsonb,'A cost already incurred that cannot be recovered','A sunk cost has already been incurred and cannot be recovered; decisions should focus on relevant future costs and benefits.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2271','business','Finance','medium','classic','What is a semi-variable cost?','["A cost with both fixed and activity-dependent parts","A cost that must remain zero","A cost that changes only with the weather","A payment that is always made in foreign currency"]'::jsonb,'A cost with both fixed and activity-dependent parts','A semi-variable cost contains a fixed portion and a portion that varies with activity.',10,2,array['finance'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2272','business','Customers','hard','classic','What is customer churn?','["The share of customers who stop using a service during a period","The number of products returned to a warehouse","The average time a customer spends in a shop","The amount a business pays to acquire a new customer"]'::jsonb,'The share of customers who stop using a service during a period','Customer churn measures how many customers stop using a product or service in a given period.',10,2,array['customers'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2273','business','Markets','medium','classic','What is a business-to-consumer transaction?','["A sale from a business directly to an individual consumer","A purchase between two government agencies","A sale from one wholesaler to another only","A loan between two banks"]'::jsonb,'A sale from a business directly to an individual consumer','B2C describes business transactions in which a company sells to individual consumers.',10,2,array['markets'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2274','business','Operations','hard','classic','What does supply chain management coordinate?','["The flow of materials, information, and goods from suppliers to customers","Only the design of a company''s logo","A worker''s daily commuting route","The calculation of a single tax form"]'::jsonb,'The flow of materials, information, and goods from suppliers to customers','Supply chain management coordinates sourcing, production, movement, and delivery of goods and information.',10,2,array['operations'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2275','business','Markets','medium','classic','What is a competitive advantage?','["A feature or capability that helps a business outperform rivals","A rule requiring every firm to set the same price","A cost that never changes with production","A list of public holidays observed by a company"]'::jsonb,'A feature or capability that helps a business outperform rivals','A competitive advantage is a capability or position that lets a business create more value than competitors.',10,2,array['markets'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2276','business','Markets','hard','classic','What is a customer acquisition cost?','["The average cost of gaining a new customer","The price a customer pays for a single product","The annual rent paid for a shop","The value of all unsold inventory"]'::jsonb,'The average cost of gaining a new customer','Customer acquisition cost estimates the marketing and sales cost of gaining a customer.',10,2,array['markets'],'en',true,'US Small Business Administration, Business Guide — https://www.sba.gov/business-guide') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2277','accounting','Statements','medium','classic','What does a statement of changes in equity report?','["Changes in owners’ equity over a reporting period","Only the cash held by a business on one date","The number of products sold by each employee","The amount of tax charged on every invoice"]'::jsonb,'Changes in owners’ equity over a reporting period','A statement of changes in equity reconciles opening and closing equity and reports movements during the period.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2278','accounting','Accounts','hard','classic','What is a contra-asset account?','["An account that reduces the reported amount of a related asset","An account used only to record sales tax","A record of customer satisfaction scores","An account that increases every liability"]'::jsonb,'An account that reduces the reported amount of a related asset','Accumulated depreciation is an example of a contra-asset that offsets a related asset balance.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2279','accounting','Reporting','medium','classic','What is an accounting estimate?','["An approximate amount based on available evidence when exact measurement is not possible","A receipt that proves a customer paid in cash","A list of all transactions entered into a journal","A rule that every asset must be sold at its original price"]'::jsonb,'An approximate amount based on available evidence when exact measurement is not possible','Accounting estimates use reasonable information and judgment to measure amounts that cannot be observed precisely.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2280','accounting','Records','hard','classic','What is a subsidiary ledger used for?','["Keeping detailed records that support a related general-ledger balance","Recording only a company’s annual profit","Listing the names of shareholders in order of age","Setting the market price of a company’s shares"]'::jsonb,'Keeping detailed records that support a related general-ledger balance','A subsidiary ledger contains details—such as individual customer balances—that support a summarized general-ledger account.',10,2,array['records'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2281','accounting','Methods','medium','classic','What does cash-basis accounting generally record?','["Income when cash is received and expenses when cash is paid","Income only when a contract is signed","Every asset at its future selling price","Transactions only at the end of a company’s financial year"]'::jsonb,'Income when cash is received and expenses when cash is paid','Under cash-basis accounting, income and expenses are generally recorded when cash is received or paid, subject to applicable rules.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2282','accounting','Accounts','medium','classic','What is a suspense account used for?','["Temporarily holding an amount whose correct account or treatment has not yet been determined","Recording only cash received from customers","Tracking the market price of company shares","Storing the list of a company’s products"]'::jsonb,'Temporarily holding an amount whose correct account or treatment has not yet been determined','A suspense account temporarily holds an entry while its correct classification or cause is investigated.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2283','accounting','Accounts','medium','classic','What is a current liability?','["An obligation expected to be settled in the operating cycle or within a year","A resource expected to provide future benefits","A payment made only by customers","An asset that cannot be sold"]'::jsonb,'An obligation expected to be settled in the operating cycle or within a year','Current liabilities are generally due within the operating cycle or twelve months, depending on the reporting framework.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2284','accounting','Records','medium','classic','What is an adjusting entry in accounting?','["An entry made at the end of a period to update accounts before financial statements are prepared","A purchase request sent to a supplier","A record of a customer’s card payment at checkout","A transfer of every balance-sheet amount into cash"]'::jsonb,'An entry made at the end of a period to update accounts before financial statements are prepared','Adjusting entries update account balances for items such as accrued or prepaid amounts before statements are prepared.',10,2,array['records'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2285','accounting','Accounts','medium','classic','What is unearned revenue?','["Payment received before the related goods or services have been provided","A bill a business has not yet paid to a supplier","An amount a customer owes for a completed sale","A reduction in the value of equipment over time"]'::jsonb,'Payment received before the related goods or services have been provided','Unearned revenue is generally recorded as a liability until the promised goods or services are provided.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2286','accounting','Reporting','hard','classic','What is a deferred tax asset?','["A future tax benefit arising from deductible temporary differences or similar items","Cash set aside to pay a supplier tomorrow","A machine that will be used to produce goods","A loan that a company has already repaid"]'::jsonb,'A future tax benefit arising from deductible temporary differences or similar items','A deferred tax asset represents tax amounts that may reduce future tax payments, subject to recognition requirements.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2287','accounting','Methods','medium','classic','What does accrual-basis accounting generally record?','["Transactions when income is earned or expenses are incurred","Every transaction only when cash changes hands","Only sales made at the end of a year","Only purchases paid for with a card"]'::jsonb,'Transactions when income is earned or expenses are incurred','Accrual accounting recognizes revenues when earned and expenses when incurred, subject to applicable rules.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2288','accounting','Records','medium','classic','What is an audit trail?','["A sequence of records that allows a transaction to be traced through a system","A forecast of future exchange rates","A list of employees who attended a meeting","A schedule for replacing office equipment"]'::jsonb,'A sequence of records that allows a transaction to be traced through a system','An audit trail links supporting records and system activity so transactions can be followed and checked.',10,2,array['records'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2289','accounting','Methods','hard','classic','What is a reversing entry in accounting?','["An entry in a new period that reverses a specified prior-period adjustment","A record that lists goods packed into a shipment","A document showing a company’s market share","A payment made to acquire a competitor"]'::jsonb,'An entry in a new period that reverses a specified prior-period adjustment','Some prior-period adjusting entries are reversed at the start of a new period to simplify recording related transactions.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2290','accounting','Reporting','hard','classic','Under IFRS, when is an impairment loss generally recognized for an asset?','["When its carrying amount exceeds its recoverable amount","When the asset is purchased for cash","When revenue is received before a service is provided","When a company pays a dividend to shareholders"]'::jsonb,'When its carrying amount exceeds its recoverable amount','Under IFRS, an impairment loss is recognized when an asset’s carrying amount exceeds its recoverable amount.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2291','accounting','Equity','medium','classic','What is a share buyback?','["When a company repurchases its own shares","When a customer returns a product to a shop","When a lender reduces a loan''s interest rate","When a firm issues a new product catalogue"]'::jsonb,'When a company repurchases its own shares','A share buyback occurs when a company purchases its own shares, subject to applicable rules.',10,2,array['equity'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2292','accounting','Methods','hard','classic','What is the matching principle in traditional accounting terminology?','["Recognizing related expenses in the period of the revenues they help generate","Recording every asset at its future selling price","Matching each employee with a customer","Making every balance sheet have two pages"]'::jsonb,'Recognizing related expenses in the period of the revenues they help generate','The matching principle associates expenses with the revenues they help produce, within the reporting framework.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2293','accounting','Accounts','hard','classic','What is an intangible asset?','["A non-physical resource such as a patent or software right","Cash held in a bank account","A machine used in production","A building owned by the business"]'::jsonb,'A non-physical resource such as a patent or software right','Intangible assets lack physical substance and may include identifiable rights such as patents.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2294','accounting','Statements','hard','classic','What does liquidity describe for a business?','["Its ability to meet short-term obligations as they fall due","The number of products made each day","The long-term popularity of a brand","The number of offices a business operates"]'::jsonb,'Its ability to meet short-term obligations as they fall due','Liquidity is the ability to meet obligations as they become due, often using readily available resources.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2295','accounting','Methods','hard','classic','What does revenue recognition address?','["When and how revenue is recorded in financial statements","The order in which customers enter a shop","How a company chooses a logo color","The method for calculating an employee''s commute"]'::jsonb,'When and how revenue is recorded in financial statements','Revenue recognition principles determine when and how an entity records income from contracts with customers.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2296','accounting','Reporting','hard','classic','What does other comprehensive income include?','["Certain gains and losses reported outside profit or loss under accounting standards","All cash received from customers during a period","Every expense paid before a reporting date","Only dividends paid to shareholders"]'::jsonb,'Certain gains and losses reported outside profit or loss under accounting standards','Other comprehensive income includes specified gains and losses that accounting standards present separately from profit or loss within comprehensive income.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2297','commerce','Trade documents','easy','classic','What is a commercial invoice used for in international trade?','["It lists goods sold and details such as price and buyer","It proves a ship has been repaired","It sets the exchange rate for a country","It replaces the need to pack goods"]'::jsonb,'It lists goods sold and details such as price and buyer','A commercial invoice describes a sale and is used in trade and customs documentation.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2298','commerce','Trade documents','medium','classic','What does a bill of lading commonly serve as?','["A receipt for shipped goods and evidence of the carriage contract","A certificate that goods are tax-free everywhere","A retail price tag for a product","A bank statement for the ship''s crew"]'::jsonb,'A receipt for shipped goods and evidence of the carriage contract','A bill of lading can serve as a receipt, evidence of a contract of carriage, and in some cases a document of title.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2299','commerce','Logistics','medium','classic','What is a bonded warehouse?','["A customs-controlled facility where imported goods may be stored before applicable duties are paid","A shop that sells only goods made locally","A shipper’s document listing the contents of every package","A market where buyers bid on used machinery"]'::jsonb,'A customs-controlled facility where imported goods may be stored before applicable duties are paid','A bonded warehouse stores goods under customs control, often allowing duties to be deferred until release.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2300','commerce','Trade rules','medium','classic','What do Incoterms rules mainly clarify in a sale of goods?','["Certain delivery responsibilities, costs, and risks between seller and buyer","The quality grade of every product","The exchange rate used by all banks","The language that must appear on an invoice"]'::jsonb,'Certain delivery responsibilities, costs, and risks between seller and buyer','Incoterms allocate specified obligations, costs, and risks in delivery between parties to a sale.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2301','commerce','Logistics','medium','classic','What does a customs broker help an importer do?','["Prepare customs documentation and arrange clearance under local rules","Set the global price of a product","Insure every shipment without a contract","Manufacture a shipping container"]'::jsonb,'Prepare customs documentation and arrange clearance under local rules','Customs brokers help prepare declarations and coordinate clearance with customs authorities.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2302','commerce','Trade rules','hard','classic','When may an exporter need an export licence?','["When regulations require authorization for certain goods, destinations, or end uses","Whenever a package is sent to another city","Only when a buyer pays in cash","Whenever a company prints a commercial invoice"]'::jsonb,'When regulations require authorization for certain goods, destinations, or end uses','Export controls may require a licence for particular products, destinations, end users, or uses; the applicable rules depend on jurisdiction.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2303','commerce','Trade rules','medium','classic','What does a customs union generally establish among its members?','["Free trade among members and a common external tariff on many imports","A shared currency and one central bank in every case","A rule that all exports must be sold at the same price","A ban on trade with every neighboring country"]'::jsonb,'Free trade among members and a common external tariff on many imports','A customs union removes many trade barriers among members and applies a common external tariff to goods from outside the union.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2304','commerce','Logistics','medium','classic','What does containerization mean in freight transport?','["Moving goods in standardized reusable containers","Wrapping every parcel in paper","Sending products only by air","Storing all goods in a retail display"]'::jsonb,'Moving goods in standardized reusable containers','Containerization uses standardized containers that can be transferred between transport modes.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2305','commerce','Trade documents','medium','classic','What is a pro forma invoice?','["A preliminary document outlining a proposed sale before the final invoice","A final court judgment about a shipment","A receipt showing that customs duty was paid","A certificate proving a product has been sold at retail"]'::jsonb,'A preliminary document outlining a proposed sale before the final invoice','A pro forma invoice gives a preliminary description and estimated value of a proposed transaction.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2306','commerce','Trade rules','hard','classic','What is the Harmonized System used for in international trade?','["Classifying traded products with standardized codes","Measuring the distance a ship travels","Setting the price of every exported product","Recording a company''s annual sales"]'::jsonb,'Classifying traded products with standardized codes','The Harmonized System is an international nomenclature for classifying traded products.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2307','commerce','Logistics','medium','classic','What does demurrage commonly charge for in container shipping?','["Keeping a container at a port terminal beyond the allowed free time","Returning an empty container before its due date","Insuring cargo against damage during a voyage","Moving goods from a warehouse to a local shop"]'::jsonb,'Keeping a container at a port terminal beyond the allowed free time','Demurrage commonly refers to charges when a container remains at a terminal beyond its permitted free time.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2308','commerce','Logistics','medium','classic','What is an advance shipping notice used to communicate?','["Details about an upcoming shipment before it arrives","The final profit made by the carrier","The design of a product’s retail package","The exchange rate used to pay a supplier"]'::jsonb,'Details about an upcoming shipment before it arrives','An advance shipping notice gives a receiver information about a shipment before delivery, such as its contents and expected arrival.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2309','commerce','Payments','medium','classic','What is a chargeback in card payments?','["A reversal of a card transaction initiated through the cardholder’s bank, often after a dispute","A discount applied automatically to every cash purchase","A fee paid to ship goods across a border","A statement showing how much stock remains in a shop"]'::jsonb,'A reversal of a card transaction initiated through the cardholder’s bank, often after a dispute','A chargeback reverses a card payment through the payment system, commonly following a dispute.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2310','commerce','Retail','medium','classic','What is an online marketplace?','["A platform where multiple sellers can offer goods or services to buyers","A customs warehouse that stores only one company''s goods","A bank account used only for international tax","A paper catalogue printed once a year"]'::jsonb,'A platform where multiple sellers can offer goods or services to buyers','An online marketplace connects buyers with offerings from multiple sellers.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2311','commerce','E-commerce','medium','classic','What is drop shipping?','["A retailer forwards an order to a supplier that ships directly to the customer","A carrier moves goods back to a factory for recycling","A customer pays a fee to collect a package","A warehouse transfers freight between two trucks"]'::jsonb,'A retailer forwards an order to a supplier that ships directly to the customer','In drop shipping, the retailer sells an item while a supplier or third party fulfills the shipment directly.',10,2,array['e-commerce'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2312','commerce','Payments','hard','classic','What is documentary collection in trade finance?','["Banks handle shipping documents against payment or a payment promise","A method that makes every export free of risk","A shipment paid for only with coins","A government grant that reimburses customs fees"]'::jsonb,'Banks handle shipping documents against payment or a payment promise','In documentary collection, banks transfer documents according to the seller''s instructions, often against payment or acceptance.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2313','commerce','Trade documents','medium','classic','What does a certificate of conformity generally attest?','["That a product meets specified standards or regulatory requirements","The country where the product was first sold","The route a cargo ship followed","The exact date a buyer made payment"]'::jsonb,'That a product meets specified standards or regulatory requirements','A certificate of conformity provides evidence that a product meets stated requirements or standards.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2314','commerce','Logistics','hard','classic','What is cross-docking in logistics?','["Transferring incoming goods to outbound transport with little storage","Keeping every shipment in a warehouse for a full year","Sending an empty container back to its manufacturer","Delivering a product only to a border checkpoint"]'::jsonb,'Transferring incoming goods to outbound transport with little storage','Cross-docking moves goods from receiving to shipping with minimal time in storage.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2315','commerce','Trade','hard','classic','What is a trade facilitation measure intended to do?','["Simplify and speed up legitimate cross-border trade procedures","Prevent all goods from crossing borders","Require every exporter to use one shipping company","Set a single retail price worldwide"]'::jsonb,'Simplify and speed up legitimate cross-border trade procedures','Trade facilitation seeks to simplify, modernize, and harmonize import and export procedures.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2316','commerce','Trade documents','hard','classic','What is cargo insurance intended to cover?','["Specified risks of loss or damage to goods during transit","Every change in a product''s market price forever","All business expenses after delivery","The cost of advertising a shipment"]'::jsonb,'Specified risks of loss or damage to goods during transit','Cargo insurance can cover agreed transit risks subject to the policy''s terms and exclusions.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2317','medical','Medical terms','easy','classic','In medical terminology, what does the suffix -itis usually mean?','["Inflammation","A surgical removal","A blood test","A bone fracture"]'::jsonb,'Inflammation','The suffix -itis commonly indicates inflammation, as in tonsillitis.',10,2,array['medical terms'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2318','medical','Care','medium','classic','What does triage do in a busy medical setting?','["Prioritizes people according to urgency of need","Assigns every patient the same waiting time","Prescribes a medicine without an assessment","Records only the names of visitors"]'::jsonb,'Prioritizes people according to urgency of need','Triage sorts patients by urgency so those needing immediate care can be prioritized.',10,2,array['care'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2319','medical','Diagnostics','easy','classic','What does an electrocardiogram record?','["Electrical activity of the heart","The mineral density of bones","The speed of blood moving through the kidneys","The electrical activity of the brain only"]'::jsonb,'Electrical activity of the heart','An electrocardiogram records electrical signals associated with the heart''s activity.',10,2,array['diagnostics'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2320','medical','Diagnostics','easy','classic','Which imaging method uses strong magnetic fields and radio waves?','["Magnetic resonance imaging","X-ray imaging only","Ultrasound only","Thermal imaging"]'::jsonb,'Magnetic resonance imaging','MRI uses strong magnetic fields and radiofrequency waves to create detailed images.',10,2,array['diagnostics'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2321','medical','Diagnostics','easy','classic','What is a biopsy?','["A sample of tissue taken for examination","A scan that measures body temperature","A medicine used to reduce fever","A device that replaces a missing limb"]'::jsonb,'A sample of tissue taken for examination','A biopsy removes cells or tissue so they can be examined, often by a pathologist.',10,2,array['diagnostics'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2322','medical','Treatment','medium','classic','What does dialysis help do when kidneys cannot adequately filter the blood?','["Remove waste products and excess fluid","Produce digestive enzymes","Repair a broken bone","Restore hearing in every patient"]'::jsonb,'Remove waste products and excess fluid','Dialysis uses a process to remove waste and excess fluid when kidney function is severely reduced.',10,2,array['treatment'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2323','medical','Medical roles','easy','classic','What does a radiologist specialize in?','["Interpreting medical imaging","Preparing all hospital meals","Designing sports equipment","Managing a country''s elections"]'::jsonb,'Interpreting medical imaging','Radiologists interpret imaging studies such as X-rays, CT scans, and MRI examinations.',10,2,array['medical roles'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2324','medical','Medical roles','medium','classic','What does a pathologist commonly examine to help diagnose disease?','["Tissue, blood, or other laboratory samples","Only a patient''s exercise schedule","The sound of a hospital alarm","A list of medicines sold in a pharmacy"]'::jsonb,'Tissue, blood, or other laboratory samples','Pathologists analyze laboratory samples such as tissues and blood to support diagnosis.',10,2,array['medical roles'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2325','medical','Research','medium','classic','What is a placebo in a clinical study?','["A comparison treatment without the active ingredient being tested","A guaranteed cure for the condition","A device used to measure pulse","A medicine that contains every possible ingredient"]'::jsonb,'A comparison treatment without the active ingredient being tested','A placebo is designed to look like a treatment but lacks the active ingredient under study.',10,2,array['research'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2326','medical','Research','medium','classic','What is a clinical trial?','["A research study that evaluates health interventions in people","A routine visit that can never collect data","A method for choosing a hospital''s paint color","A test used only to check eyesight"]'::jsonb,'A research study that evaluates health interventions in people','Clinical trials study health interventions in human participants under defined protocols.',10,2,array['research'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2327','medical','Infection prevention','medium','classic','Where is an antiseptic intended to be used?','["On living tissue to reduce microorganisms","Only on metal surgical tools","Only on floors and work surfaces","Inside a battery to prevent corrosion"]'::jsonb,'On living tissue to reduce microorganisms','Antiseptics are used on living tissue; disinfectants are generally used on inanimate surfaces.',10,2,array['infection prevention'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2328','medical','Care','medium','classic','What is a main goal of palliative care?','["Relieve symptoms and support quality of life","Replace every other form of treatment","Guarantee that an illness will be cured","Provide care only during surgery"]'::jsonb,'Relieve symptoms and support quality of life','Palliative care focuses on relief from symptoms and stress and can accompany other treatments.',10,2,array['care'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2329','medical','Medical terms','easy','classic','What does chronic generally mean when describing a condition?','["Long-lasting or recurring over time","Beginning suddenly and ending within minutes","Caused only by an injury","Present only during sleep"]'::jsonb,'Long-lasting or recurring over time','Chronic conditions persist or recur over an extended period.',10,2,array['medical terms'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2330','medical','Medical terms','medium','classic','What does benign generally mean when describing a tumor?','["It is not cancerous","It is always harmless in every location","It has spread to distant organs","It is caused by a virus"]'::jsonb,'It is not cancerous','A benign tumor is non-cancerous, though its effects can depend on size and location.',10,2,array['medical terms'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2331','medical','Diagnostics','medium','classic','What does a pulse oximeter estimate?','["The percentage of hemoglobin carrying oxygen in the blood","The number of calories a person ate","The amount of calcium in a bone","The electrical activity of the stomach"]'::jsonb,'The percentage of hemoglobin carrying oxygen in the blood','A pulse oximeter estimates peripheral oxygen saturation and pulse rate.',10,2,array['diagnostics'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2332','medical','Treatment','medium','classic','What does anesthesia do during a medical procedure?','["Reduces or prevents sensation, awareness, or pain as intended","Measures the size of a patient''s bones","Identifies the organism in every infection","Replaces blood lost during an injury"]'::jsonb,'Reduces or prevents sensation, awareness, or pain as intended','Anesthesia is used to prevent or reduce pain and awareness during procedures, depending on its type.',10,2,array['treatment'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2333','medical','Public health','hard','classic','What does epidemiology study?','["The distribution and causes of health-related conditions in populations","The design of hospital furniture","The chemistry of a single medicine only","The movement of planets around the Sun"]'::jsonb,'The distribution and causes of health-related conditions in populations','Epidemiology studies the distribution and determinants of health events in populations.',10,2,array['public health'],'en',true,'MedlinePlus (U.S. National Library of Medicine) and WHO fact sheets — https://medlineplus.gov/ ; https://www.who.int/news-room/fact-sheets') on conflict (id) do nothing;
