insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2368','physics','Heat','easy','classic','How can thermal radiation transfer energy?','["By electromagnetic waves, even through a vacuum","Only by direct contact between solids","Only through moving liquid water","By sending atoms through a wire"]'::jsonb,'By electromagnetic waves, even through a vacuum','Radiation carries energy through electromagnetic waves and does not require a material medium.',10,2,array['heat'],'en',true,'OpenStax College Physics and NIST SI Units — https://openstax.org/details/books/college-physics-2e ; https://www.nist.gov/pml/owm/si-units') on conflict (id) do nothing;
