insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2398','biology','Cells','medium','classic','What is a major function of the Golgi apparatus?','["Modify, sort, and package proteins and other molecules for transport","Produce ATP by breaking down glucose","Copy the cell’s DNA before division","Control the opening of leaf pores"]'::jsonb,'Modify, sort, and package proteins and other molecules for transport','The Golgi apparatus processes and sorts molecules, packaging them for transport to destinations in or outside the cell.',10,2,array['cells'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2399','biology','Cells','medium','classic','What is apoptosis?','["A regulated process of programmed cell death","The movement of water across a membrane","The copying of DNA before cell division","The production of sugars in a leaf"]'::jsonb,'A regulated process of programmed cell death','Apoptosis is a regulated process by which cells undergo programmed death.',10,2,array['cells'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2400','biology','Cells','medium','classic','What is a stem cell?','["A cell that can self-renew and develop into one or more specialized cell types","A cell found only in the stem of a plant","A mature cell that cannot divide","A molecule that carries oxygen in blood"]'::jsonb,'A cell that can self-renew and develop into one or more specialized cell types','Stem cells can self-renew and can differentiate into specialized cell types, with potential varying by stem-cell type.',10,2,array['cells'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2401','biology','Cells','medium','classic','What is the main result of meiosis in animals?','["Formation of cells with half the usual chromosome number","Production of two identical body cells","Conversion of proteins into sunlight","Duplication of every organ in the body"]'::jsonb,'Formation of cells with half the usual chromosome number','Meiosis reduces chromosome number and helps produce gametes.',10,2,array['cells'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2402','biology','Evolution','medium','classic','What is natural selection?','["A process where inherited traits that aid reproduction tend to become more common","A process in which organisms choose their own genes","A sudden change in climate every year","A method for breeding only plants in a laboratory"]'::jsonb,'A process where inherited traits that aid reproduction tend to become more common','Natural selection changes trait frequencies when inherited differences affect survival or reproduction.',10,2,array['evolution'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
