insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2405','biology','Plant biology','medium','classic','What is fertilization in a flowering plant?','["Fusion of male and female gametes, usually within an ovule","Transfer of pollen from anther to stigma","Release of water vapor from a leaf","Movement of a seed away from its parent plant"]'::jsonb,'Fusion of male and female gametes, usually within an ovule','After pollination, fertilization occurs when male and female gametes fuse in the ovule.',10,2,array['plant biology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2406','biology','Microbiology','medium','classic','What is a key feature of prokaryotic cells?','["They lack a membrane-bound nucleus","They contain a large membrane-bound nucleus","They are always larger than animal cells","They contain chloroplasts in every species"]'::jsonb,'They lack a membrane-bound nucleus','Prokaryotic cells lack a membrane-bound nucleus; their DNA is in a nucleoid region.',10,2,array['microbiology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2407','biology','Microbiology','medium','classic','How do viruses typically reproduce?','["By using a host cell''s machinery","By dividing independently like a bacterium","By photosynthesizing in sunlight","By forming seeds in soil"]'::jsonb,'By using a host cell''s machinery','Viruses replicate by entering host cells and using cellular machinery to make viral components.',10,2,array['microbiology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2408','biology','Ecology','medium','classic','What is a detritivore?','["An organism that ingests dead organic material and breaks it into smaller pieces","An organism that makes food from sunlight","A predator that eats only live prey","A mineral dissolved in groundwater"]'::jsonb,'An organism that ingests dead organic material and breaks it into smaller pieces','Detritivores ingest dead organic matter; decomposers such as fungi and bacteria break it down chemically.',10,2,array['ecology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2409','biology','Ecology','medium','classic','What does carrying capacity mean for a population?','["The population size an environment can sustain over time","The number of animals that can fit in one vehicle","The total number of species on Earth","The speed at which a predator runs"]'::jsonb,'The population size an environment can sustain over time','Carrying capacity is the population size that available resources can support over time.',10,2,array['ecology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2410','biology','Genetics','medium','classic','What is a mutation?','["A change in genetic material","A temporary change in body temperature","A type of food chain","The movement of pollen between flowers"]'::jsonb,'A change in genetic material','A mutation is a change in DNA sequence or other genetic material.',10,2,array['genetics'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2411','biology','Genetics','easy','classic','What is a dominant allele in a simple inheritance model?','["An allele whose effect can appear with one copy","An allele that is always harmful","An allele found only in bacteria","An allele that disappears whenever it is inherited"]'::jsonb,'An allele whose effect can appear with one copy','In a simple dominance model, one copy of a dominant allele can affect the observed trait.',10,2,array['genetics'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2412','biology','Biological systems','medium','classic','What is homeostasis?','["Maintaining relatively stable internal conditions","Changing species every generation","Producing food only during winter","Moving a habitat to a new continent"]'::jsonb,'Maintaining relatively stable internal conditions','Homeostasis is the regulation of internal conditions within ranges compatible with life.',10,2,array['biological systems'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2413','biology','Ecology','hard','classic','What is an ecological niche?','["The role of a species and how it uses resources and interacts in its environment","The physical address of an individual animal","A list of all minerals in a habitat","A temporary change in weather over one afternoon"]'::jsonb,'The role of a species and how it uses resources and interacts in its environment','A niche describes a species'' role, resource use, and interactions within an ecosystem.',10,2,array['ecology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2414','biology','Microbiology','hard','classic','Which statement best distinguishes archaea from bacteria?','["They are separate domains of prokaryotic life with important molecular differences","Archaea are animals and bacteria are plants","All archaea cause disease while bacteria do not","Bacteria have nuclei but archaea do not"]'::jsonb,'They are separate domains of prokaryotic life with important molecular differences','Archaea and Bacteria are distinct domains of prokaryotes, differing in cell chemistry and genetics.',10,2,array['microbiology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2415','biology','Genetics','medium','classic','What is a codon in molecular biology?','["A sequence of three nucleotides in messenger RNA that specifies an amino acid or a stop signal","A complete chromosome found only in bacteria","A protein that copies every cell membrane","A lipid that stores energy in seeds"]'::jsonb,'A sequence of three nucleotides in messenger RNA that specifies an amino acid or a stop signal','A codon is a three-nucleotide unit in mRNA that corresponds to an amino acid or a translation stop signal.',10,2,array['genetics'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2416','biology','Ecology','hard','classic','What is a population in ecology?','["Members of the same species living in a particular area","All ecosystems on Earth combined","Only the plants in one habitat","A group of different species from several continents"]'::jsonb,'Members of the same species living in a particular area','An ecological population consists of individuals of the same species in a given area.',10,2,array['ecology'],'en',true,'OpenStax Biology 2e — https://openstax.org/details/books/biology-2e') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2417','mathematics','Sets','easy','classic','What does the union A union B contain?','["Elements that are in A, in B, or in both","Only elements common to both sets","Elements that are in neither set","Only the first element of A"]'::jsonb,'Elements that are in A, in B, or in both','The union of two sets contains every element that belongs to at least one of them.',10,2,array['sets'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2418','mathematics','Sequences','easy','classic','What is the common difference in the arithmetic sequence 4, 9, 14, 19?','["5","4","9","14"]'::jsonb,'5','Subtract consecutive terms to find the common difference: 9 minus 4 equals 5.',10,2,array['sequences'],'en',true,'Khan Academy mathematics topics — https://www.khanacademy.org/math ; Encyclopaedia Britannica, Mathematics — https://www.britannica.com/science/mathematics') on conflict (id) do nothing;
