insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2439','health','Community health','medium','classic','What are social determinants of health?','["Conditions in the places where people live, learn, work, and age","Only the genes inherited from parents","A list of medicines in a pharmacy","The number of hospitals in one city"]'::jsonb,'Conditions in the places where people live, learn, work, and age','Social determinants include conditions such as housing, education, work, and community resources.',10,2,array['community health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2440','health','Prevention','easy','classic','What is primary prevention intended to do?','["Reduce the chance that a disease or injury occurs","Treat complications after they have developed","Record a patient''s height after a visit","Replace emergency care in every situation"]'::jsonb,'Reduce the chance that a disease or injury occurs','Primary prevention aims to prevent a condition before it occurs, for example through vaccination or safer environments.',10,2,array['prevention'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2441','health','Prevention','medium','classic','What is secondary prevention generally aimed at?','["Detecting a condition early so it can be addressed promptly","Preventing exposure to every risk in the environment","Providing rehabilitation after a long-term injury only","Measuring the price of medical equipment"]'::jsonb,'Detecting a condition early so it can be addressed promptly','Secondary prevention focuses on early detection and prompt response to disease or risk.',10,2,array['prevention'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2442','health','Nutrition','easy','classic','What are micronutrients?','["Vitamins and minerals needed in relatively small amounts","The body''s largest bones","Only fats and carbohydrates","Foods that contain no nutrients"]'::jsonb,'Vitamins and minerals needed in relatively small amounts','Micronutrients include vitamins and minerals required in small amounts for normal body functions.',10,2,array['nutrition'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2443','health','Nutrition','easy','classic','Which group includes the main macronutrients in the human diet?','["Carbohydrates, proteins, and fats","Vitamins, minerals, and water only","Oxygen, nitrogen, and helium","Fiber, salt, and caffeine only"]'::jsonb,'Carbohydrates, proteins, and fats','Carbohydrates, proteins, and fats are commonly classified as macronutrients.',10,2,array['nutrition'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2444','health','Prevention','medium','classic','What is a health screening intended to do?','["Look for possible disease or risk before symptoms are noticed","Provide a final diagnosis in every case","Replace all conversations with a clinician","Guarantee that a person will never become ill"]'::jsonb,'Look for possible disease or risk before symptoms are noticed','Screening looks for possible conditions in people who may not yet have symptoms; it is not a diagnosis by itself.',10,2,array['prevention'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2445','health','Everyday health','easy','classic','What is a risk factor?','["A characteristic or exposure associated with a higher chance of an outcome","A guarantee that a disease will occur","A treatment that works for every person","A measure of a person''s shoe size"]'::jsonb,'A characteristic or exposure associated with a higher chance of an outcome','A risk factor is associated with an increased likelihood of an outcome but does not guarantee it.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2446','health','Everyday health','easy','classic','What is a protective factor?','["A condition or behavior that can lower the likelihood of harm","A guarantee that no illness can occur","A type of hospital building","A device that measures rainfall"]'::jsonb,'A condition or behavior that can lower the likelihood of harm','Protective factors can reduce risk or support positive health outcomes.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2447','health','Mental well-being','easy','classic','What does mental well-being include?','["Emotional, psychological, and social well-being","Only the absence of any physical illness","The ability to avoid all difficult feelings","A person''s score on a math test"]'::jsonb,'Emotional, psychological, and social well-being','Mental well-being includes emotional, psychological, and social aspects of life.',10,2,array['mental well-being'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2448','health','Everyday health','medium','classic','Why can short movement breaks be useful during long periods of sitting?','["They interrupt prolonged stillness and allow a person to move","They replace every form of physical activity","They guarantee perfect posture for life","They prevent the need for sleep"]'::jsonb,'They interrupt prolonged stillness and allow a person to move','Brief movement breaks can interrupt long periods of sedentary behavior; individual needs vary.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2449','health','Community health','medium','classic','What is a communicable disease?','["A disease that can spread between organisms by some route","A condition caused only by a broken bone","A disease that is always inherited","A condition that cannot be detected"]'::jsonb,'A disease that can spread between organisms by some route','Communicable diseases can spread through routes such as contact, droplets, vectors, or contaminated food and water.',10,2,array['community health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2450','health','Community health','medium','classic','What is a noncommunicable disease?','["A condition that is not transmitted directly from one person to another","A disease that affects only one person worldwide","An illness caused only by bacteria","A condition that has no risk factors"]'::jsonb,'A condition that is not transmitted directly from one person to another','Noncommunicable diseases do not spread directly from person to person, though many have complex causes.',10,2,array['community health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2451','health','Everyday health','easy','classic','What is first aid?','["Immediate assistance given to someone who is injured or suddenly ill","A long-term treatment plan written by a specialist","A method for measuring a country''s population","A way to replace professional emergency services"]'::jsonb,'Immediate assistance given to someone who is injured or suddenly ill','First aid is initial help provided until professional care is available or the person recovers.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2452','health','Everyday health','medium','classic','What does a serving size on a nutrition label describe?','["The reference amount used for the listed nutrition information","The exact amount every person must eat","The total food made by a factory in a day","The weight of the package material"]'::jsonb,'The reference amount used for the listed nutrition information','Nutrition facts are reported for a stated serving size, which may differ from an individual''s portion.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2453','health','Mental well-being','medium','classic','What is one purpose of a relaxation technique such as slow breathing?','["To support calm and manage stress in the moment","To diagnose every mental health condition","To replace all forms of professional care","To ensure that stressful events never happen"]'::jsonb,'To support calm and manage stress in the moment','Relaxation strategies can help some people manage momentary stress, though they are not a substitute for needed care.',10,2,array['mental well-being'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2454','health','Community health','hard','classic','What does health equity aim to promote?','["Fair opportunities for everyone to achieve their best possible health","Identical health outcomes for every person","The same medical treatment regardless of need","Health services only in large cities"]'::jsonb,'Fair opportunities for everyone to achieve their best possible health','Health equity seeks fair opportunity by addressing avoidable barriers and differences in conditions.',10,2,array['community health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2455','health','Everyday health','hard','classic','What does informed consent involve?','["Understanding relevant information and voluntarily agreeing to a procedure or study","Signing any form without an explanation","Allowing someone else to decide without discussion","Guaranteeing that a treatment will succeed"]'::jsonb,'Understanding relevant information and voluntarily agreeing to a procedure or study','Informed consent involves understandable information, capacity, and a voluntary choice, subject to applicable rules.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2456','health','Everyday health','hard','classic','What is a health care referral?','["A request or direction for a person to receive care from another service or specialist","A guarantee that a diagnosis is correct","A record of a person''s daily meals","A way to cancel all future appointments"]'::jsonb,'A request or direction for a person to receive care from another service or specialist','A referral connects a patient with another professional or service for evaluation or care.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2457','literature','Poetry','medium','classic','What is a common rhyme scheme for a limerick?','["AABBA","ABAB","ABBAAB","No repeated rhyme pattern"]'::jsonb,'AABBA','A traditional limerick has five lines and commonly follows an AABBA rhyme scheme.',10,2,array['poetry'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2458','literature','Drama','medium','classic','What is a soliloquy in a play?','["A speech in which a character speaks thoughts aloud, often while alone","A list of actors printed on a poster","A short note at the end of a book","A scene with no spoken words and no action"]'::jsonb,'A speech in which a character speaks thoughts aloud, often while alone','A soliloquy lets a character express thoughts aloud, often when no other character is present.',10,2,array['drama'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2459','literature','Poetry','medium','classic','What is blank verse?','["Unrhymed poetry written in a regular meter, often iambic pentameter","Poetry with no rhythm or line breaks","A poem printed without ink","A song that contains no vowels"]'::jsonb,'Unrhymed poetry written in a regular meter, often iambic pentameter','Blank verse is unrhymed metrical poetry, often written in iambic pentameter in English.',10,2,array['poetry'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2460','literature','Genres','easy','classic','What is satire?','["Writing that uses humor, irony, or exaggeration to criticize","A factual list of dates only","A poem that must have fourteen lines","A story told without any characters"]'::jsonb,'Writing that uses humor, irony, or exaggeration to criticize','Satire uses techniques such as irony or exaggeration to expose or criticize human behavior and institutions.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2461','literature','Genres','medium','classic','What is an allegory?','["A narrative whose characters or events represent broader ideas","A story made only from dialogue","A poem with exactly two rhyming lines","A book written by an anonymous editor"]'::jsonb,'A narrative whose characters or events represent broader ideas','An allegory communicates broader ideas through symbolic characters, actions, or settings.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2462','literature','Structure','easy','classic','What is an epilogue?','["A concluding section after the main story","A list of chapters before the story","A note explaining a word in the middle of a page","The title printed on a book''s spine"]'::jsonb,'A concluding section after the main story','An epilogue appears after the main narrative and may show what happens later.',10,2,array['structure'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2463','literature','Structure','easy','classic','What is a prologue?','["An introductory section before the main work","The final scene after the ending","A list of page numbers","A character''s private speech"]'::jsonb,'An introductory section before the main work','A prologue introduces a work or supplies context before the main narrative begins.',10,2,array['structure'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2464','literature','Storytelling','medium','classic','What is foreshadowing?','["Hints that suggest events that may happen later","A story told backward from the final page","A list of characters in alphabetical order","A description of the book''s printing paper"]'::jsonb,'Hints that suggest events that may happen later','Foreshadowing plants clues or suggestions about later events in a narrative.',10,2,array['storytelling'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2465','literature','Storytelling','easy','classic','What is a flashback in a story?','["A scene that presents an event from an earlier time","A prediction of a future event","A list of characters'' names","A repeated sound at the end of each line"]'::jsonb,'A scene that presents an event from an earlier time','A flashback interrupts the present narrative to show an earlier event.',10,2,array['storytelling'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2466','literature','Storytelling','medium','classic','Who is the narrator of a story?','["The voice or character that tells the story","The publisher who printed the book","The reader who chooses a favorite character","The person who designed the cover"]'::jsonb,'The voice or character that tells the story','The narrator is the voice that recounts the events of a narrative.',10,2,array['storytelling'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2467','literature','Storytelling','easy','classic','What is imagery in literature?','["Language that evokes sensory experience","A list of every chapter title","A method for printing pictures on a cover","A rule that every character must rhyme"]'::jsonb,'Language that evokes sensory experience','Imagery uses descriptive language that appeals to senses such as sight, sound, or touch.',10,2,array['storytelling'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2468','literature','Poetry','easy','classic','What is a couplet?','["Two consecutive lines of poetry, often linked by rhyme or rhythm","A poem with exactly two characters","A stanza with five lines","A collection of unrelated essays"]'::jsonb,'Two consecutive lines of poetry, often linked by rhyme or rhythm','A couplet is a pair of consecutive poetic lines, often rhyming or sharing a meter.',10,2,array['poetry'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2469','literature','Genres','medium','classic','What is an elegy traditionally written to express?','["Grief or reflection, often for someone who has died","Instructions for operating a machine","A humorous advertisement for a product","A list of characters in a play"]'::jsonb,'Grief or reflection, often for someone who has died','An elegy is a poem or work of reflection and mourning, often connected with loss.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2470','literature','Genres','medium','classic','What is an epistolary novel?','["A novel told through documents such as letters, diary entries, or messages","A poem that has exactly fourteen lines","A play written only as stage directions","A story that contains no narrator"]'::jsonb,'A novel told through documents such as letters, diary entries, or messages','An epistolary novel presents its narrative through documents such as letters or diary entries.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2471','literature','Genres','medium','classic','How does a memoir generally differ from a full autobiography?','["A memoir focuses on selected experiences or themes from the author''s life","A memoir is always written by a friend","An autobiography can contain no personal memories","A memoir is a fictional play"]'::jsonb,'A memoir focuses on selected experiences or themes from the author''s life','Memoirs usually focus on particular experiences or themes rather than covering an entire life.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2472','literature','Storytelling','medium','classic','What is dramatic irony?','["The audience knows something important that a character does not","A character tells a joke during every scene","A story has no ending","A play contains only songs"]'::jsonb,'The audience knows something important that a character does not','Dramatic irony occurs when the audience has information that a character lacks.',10,2,array['storytelling'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2473','literature','Genres','easy','classic','What is a biography?','["An account of a person''s life written by someone else","A fictional poem with no characters","A dictionary of technical terms","A list of a person''s future goals"]'::jsonb,'An account of a person''s life written by someone else','A biography is a written account of a person''s life by another author.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2474','literature','Poetry','medium','classic','What is an allusion in literature?','["A brief reference to a person, event, or work outside the text","A full summary printed at the end of every chapter","A repeated rhyme at the end of each stanza","A word that imitates a sound"]'::jsonb,'A brief reference to a person, event, or work outside the text','An allusion indirectly refers to a well-known person, event, text, or idea.',10,2,array['poetry'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2475','literature','Drama','medium','classic','What is a stage direction in a play?','["An instruction about movement, setting, sound, or performance","A speech delivered by the audience","A list of books sold at the theatre","A poem printed before the title page"]'::jsonb,'An instruction about movement, setting, sound, or performance','Stage directions guide performance details and are usually distinct from spoken dialogue.',10,2,array['drama'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2476','literature','Genres','hard','classic','What is an unreliable narrator?','["A narrator whose account may be incomplete, biased, or misleading","A narrator who appears in every chapter","A narrator who tells a story using only numbers","A narrator who cannot describe any event"]'::jsonb,'A narrator whose account may be incomplete, biased, or misleading','An unreliable narrator''s perspective cannot be accepted as fully accurate without question.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict (id) do nothing;
