insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2479','food','Cooking methods','medium','classic','What does sous-vide cooking involve?','["Cooking food sealed in a bag in a temperature-controlled water bath","Heating food briefly in boiling water and then cooling it","Cooking food over an open flame without a pan","Drying food in direct sunlight only"]'::jsonb,'Cooking food sealed in a bag in a temperature-controlled water bath','Sous-vide cooks sealed food in a carefully controlled water bath, often at a relatively steady temperature.',10,2,array['cooking methods'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict (id) do nothing;
