insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2490','food','Food science','medium','classic','What is a brine?','["A solution of salt in water used for food preparation","A mixture of flour and butter","A dry spice rubbed only on fruit","A type of baking pan"]'::jsonb,'A solution of salt in water used for food preparation','A brine is a salt solution often used to season or preserve foods.',10,2,array['food science'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict (id) do nothing;
