insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2502','arts','Painting','medium','classic','What is impasto in painting?','["Paint applied thickly so that brushstrokes or texture remain visible","A technique for drawing with parallel lines only","A print made by pressing a carved block into paper","A painting made exclusively on wet plaster"]'::jsonb,'Paint applied thickly so that brushstrokes or texture remain visible','Impasto is a thick application of paint that can leave a raised, textured surface.',10,2,array['painting'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
