insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2507','arts','Sculpture','medium','classic','What is assemblage in visual art?','["A three-dimensional work made by combining found or manufactured objects","A line of text printed under a photograph","A painting made only on wet plaster","A poem arranged into fourteen lines"]'::jsonb,'A three-dimensional work made by combining found or manufactured objects','Assemblage is a sculptural process that combines objects into a three-dimensional work.',10,2,array['sculpture'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2508','arts','Sculpture','medium','classic','What is a maquette?','["A small preliminary model used to develop a sculpture or design","A tiny piece of colored tile in a mosaic","A drawing that records a landscape from above","A print made from an engraved plate"]'::jsonb,'A small preliminary model used to develop a sculpture or design','A maquette is a small-scale model made to plan or test a larger sculpture or design.',10,2,array['sculpture'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2509','arts','Painting','medium','classic','What does trompe-l’œil aim to do?','["Create an illusion that a painted object or scene appears real or three-dimensional","Show only objects arranged on a table","Make every color appear less saturated","Represent a subject using raised mosaic pieces"]'::jsonb,'Create an illusion that a painted object or scene appears real or three-dimensional','Trompe-l’œil is an illusionistic technique intended to make depicted objects appear convincingly real.',10,2,array['painting'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2510','arts','Art history','hard','classic','What is a readymade in modern art?','["An existing manufactured object presented as an artwork","A painting made only on wet plaster","A sculpture carved from one block of stone","A small preliminary model for a larger sculpture"]'::jsonb,'An existing manufactured object presented as an artwork','A readymade is an ordinary manufactured object selected and presented as art, a practice famously associated with Marcel Duchamp.',10,2,array['art history'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2511','arts','Art history','medium','classic','Which art movement is associated with fragmented forms and multiple viewpoints?','["Cubism","Impressionism","Baroque","Neoclassicism"]'::jsonb,'Cubism','Cubist artists explored geometric forms and multiple viewpoints in a single composition.',10,2,array['art history'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2512','arts','Art history','medium','classic','Which movement is associated with fleeting effects of light and everyday scenes?','["Impressionism","Surrealism","Futurism","Constructivism"]'::jsonb,'Impressionism','Impressionism emphasized effects of light and color and often depicted contemporary life.',10,2,array['art history'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2513','arts','Art history','medium','classic','What did Surrealist artists often explore?','["Dreams, imagination, and unexpected combinations","Only exact architectural blueprints","The chemistry of metals in a laboratory","Strict copies of ancient maps"]'::jsonb,'Dreams, imagination, and unexpected combinations','Surrealism explored dreamlike imagery and unexpected juxtapositions.',10,2,array['art history'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2514','arts','Drawing','medium','classic','What is hatching in drawing?','["Using groups of parallel lines to suggest shading or tone","Applying paint in thick raised layers","Combining three hinged panels into one artwork","Printing an image from a grease-treated stone"]'::jsonb,'Using groups of parallel lines to suggest shading or tone','Hatching uses parallel lines, often varied in spacing or direction, to represent tone and form.',10,2,array['drawing'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2515','arts','Conservation','medium','classic','What is art conservation intended to do?','["Preserve artworks and slow or address deterioration","Change every artwork to match current fashion","Remove all evidence of an artist''s materials","Guarantee that no artwork will ever age"]'::jsonb,'Preserve artworks and slow or address deterioration','Art conservation seeks to preserve cultural objects while respecting their materials and history.',10,2,array['conservation'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2516','arts','Design','medium','classic','What is mixed media in visual art?','["An artwork made using more than one material or artistic medium","A painting made with one pigment only","A sculpture carved from one block of stone","A photograph that contains no colors"]'::jsonb,'An artwork made using more than one material or artistic medium','Mixed-media artworks combine two or more materials or media in a single work.',10,2,array['design'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict (id) do nothing;
